/* Finot Académie — Compétences numériques (Pix) au collège, année scolaire 2026-2027 : 32 chapitres reconstruits (pix6a … pix3h).
   Références : cadre de référence des compétences numériques (CRCN), article D. 121-1 du Code de l’éducation (5 domaines, 16 compétences,
   8 niveaux) ; note de service du 23 janvier 2026 « Modalités de formation, d’évaluation et de certification des compétences numériques »
   (NOR MENE2527173N), BO n°6 du 5 février 2026 : attestation de sensibilisation au numérique en fin de 6e (deux parcours Pix, au moins
   50 % de réussite à chacun), parcours Pix obligatoires sur l’IA en 4e (mise en œuvre progressive 2025-2027), certification Pix obligatoire
   en 3e (32 questions, 1 h 45 de test, niveau global attendu : niveau 3 « Indépendant 1 »), sans incidence sur le DNB. */
(function(){
'use strict';
const MQ=window.MQCollege;if(!MQ)return;const H=MQ.H;
const {R,P,ch,num,txt,order,tf,bank,pairs,sort,seq,mix,pickN,shuffle,nf}=H;
const C=(d,u,ex,m,a,r)=>({d,u,ex,m,a,r});const T=(t,h)=>({t,h});
const NS='Note de service du 23 janvier 2026, modalités de formation, d’évaluation et de certification des compétences numériques (NOR MENE2527173N), BO n°6 du 5 février 2026';
const CRCN='Cadre de référence des compétences numériques (CRCN), article D. 121-1 du Code de l’éducation';
const D1='CRCN — domaine 1 « Information et données »',D2='CRCN — domaine 2 « Communication et collaboration »',D3='CRCN — domaine 3 « Création de contenus »',D4='CRCN — domaine 4 « Protection et sécurité »',D5='CRCN — domaine 5 « Environnement numérique »';
/* Banque de situations de mots de passe : force estimée */
const PWD=[['soleil','faible : un mot du dictionnaire'],['123456','faible : suite de chiffres très utilisée'],['azerty','faible : suite du clavier'],['Lucas2013','faible : prénom et année de naissance'],['motdepasse','faible : mot courant'],['Ch@t-Vert-Nuage-71!','robuste : long, varié et difficile à deviner'],['T7#qZ!m2pL9w','robuste : long et aléatoire'],['Velo-Bleu-Pluie-Marche','robuste : phrase de passe longue']];
const pwdStrength=pw=>{let s=0;if(pw.length>=12)s++;if(/[a-z]/.test(pw)&&/[A-Z]/.test(pw))s++;if(/\d/.test(pw))s++;if(/[^\w]/.test(pw))s++;return s;};
const SIZES=[['ko',1e3],['Mo',1e6],['Go',1e9],['To',1e12]];

MQ.add('pix','6',[
{id:'pix6a',name:'Se connecter et gérer ses comptes',icon:'🔐',domain:'Environnement numérique',
 refs:[D5+', compétence 5.2 « Évoluer dans un environnement numérique »',D4+', compétence 4.1 « Sécuriser l’environnement numérique »',NS],
 tip:'Un identifiant dit QUI tu es, un mot de passe PROUVE que c’est toi : l’identifiant peut être connu, le mot de passe jamais.',
 c:C(`Au collège, tu utilises plusieurs comptes : l’ENT, Pix, parfois une messagerie. Chaque compte s’ouvre avec un <b>identifiant</b> et un <b>mot de passe</b>. Bien les gérer, c’est protéger ton travail et ta vie privée.`,
  [T('Identifiant, mot de passe, session',`<p>L’<b>identifiant</b> (nom d’utilisateur, adresse électronique) désigne le compte ; le <b>mot de passe</b> est secret et prouve que c’est bien toi. Ouvrir une <b>session</b>, c’est se connecter ; la fermer, c’est se <b>déconnecter</b>.</p><p>Sur un ordinateur partagé (CDI, salle informatique), on se déconnecte toujours à la fin et on ne laisse pas le navigateur « mémoriser » le mot de passe.</p>`),
   T('Bonnes habitudes',`<p>Ne jamais prêter son mot de passe, même à un ami. Utiliser un mot de passe <b>différent</b> pour chaque compte important. En cas d’oubli, utiliser la procédure « mot de passe oublié » ou demander à un adulte (professeur, administrateur de l’ENT).</p><p>Si quelqu’un a utilisé ton compte, préviens un adulte et change ton mot de passe.</p>`)],
  [{q:'Léa termine son travail sur un ordinateur du CDI. Que doit-elle faire ?',s:['Enregistrer son travail dans son espace (ENT ou clé autorisée).','Se déconnecter de tous ses comptes (ENT, Pix).','Fermer le navigateur : le poste est prêt pour l’élève suivant.']}],
  ['Je vérifie que je suis sur le bon site (adresse officielle).','Je saisis mon identifiant puis mon mot de passe sans que personne ne regarde.','Je travaille, puis je me déconnecte.','En cas de problème, je préviens un adulte.'],
  ['Partir sans se déconnecter sur un ordinateur partagé.','Donner son mot de passe à un camarade « pour qu’il rende le devoir ».','Utiliser le même mot de passe partout.'],
  ['Identifiant : qui je suis ; mot de passe : secret.','Toujours se déconnecter sur un poste partagé.','Un mot de passe différent par compte important.']),
 g:mix([bank([
  ['Quelle information doit rester secrète ?','le mot de passe',['l’identifiant','le nom du site','le nom du collège'],'Le mot de passe prouve ton identité : il ne se partage jamais.'],
  ['Tu as fini de travailler sur un ordinateur du CDI. Que fais-tu ?','je me déconnecte de mes comptes',['je laisse ma session ouverte pour la prochaine fois','je note mon mot de passe sur un post-it','j’éteins l’écran seulement'],'Sinon, l’élève suivant pourrait utiliser ton compte.'],
  ['Un camarade te demande ton mot de passe de l’ENT pour « regarder une note ». Que fais-tu ?','je refuse',['je le lui donne s’il est mon ami','je le lui écris sur papier','je le lui envoie par message'],'Un mot de passe est personnel, même entre amis.'],
  ['Le navigateur propose d’enregistrer ton mot de passe sur un ordinateur du collège. Tu…','refuses',['acceptes','acceptes et le notes aussi','acceptes pour tous tes comptes'],'Sur un poste partagé, d’autres utilisateurs y auraient accès.'],
  ['Tu as oublié ton mot de passe. Que fais-tu ?','j’utilise « mot de passe oublié » ou je demande à un adulte',['je crée un nouveau compte avec un faux nom','j’essaie au hasard 100 fois','j’utilise le compte d’un camarade'],'C’est la procédure prévue.'],
  ['Qu’est-ce qu’un identifiant ?','le nom qui désigne ton compte',['un mot de passe très long','un logiciel antivirus','une adresse de site'],'Il peut être connu des autres, contrairement au mot de passe.'],
  ['Que signifie « se déconnecter » ?','fermer sa session sur un service',['éteindre le Wi-Fi','supprimer son compte','oublier son mot de passe'],'On quitte son compte pour qu’il ne reste pas ouvert.'],
  ['Ton compte a été utilisé par quelqu’un d’autre. Que fais-tu ?','je préviens un adulte et je change mon mot de passe',['je ne dis rien','je supprime tous mes fichiers','j’utilise son compte à mon tour'],'Il faut sécuriser le compte au plus vite.',2],
  ['Pourquoi utiliser un mot de passe différent pour chaque compte ?','si un mot de passe est volé, les autres comptes restent protégés',['c’est obligatoire par la loi','pour l’oublier plus vite','parce que les sites refusent les mêmes'],'Un seul mot de passe pour tout est risqué.',2],
  ['L’ENT d’un collège est…','un espace numérique de travail (cahier de textes, messagerie, ressources)',['un jeu vidéo','un réseau social public','un antivirus'],'ENT = environnement numérique de travail.'],
  {tf:'On peut laisser sa session ouverte sur un ordinateur partagé si on revient vite.',v:false,e:'Quelqu’un peut l’utiliser pendant ton absence.'},
  {tf:'Un professeur ne te demandera jamais ton mot de passe.',v:true,e:'Les adultes peuvent réinitialiser un mot de passe sans le connaître.',d:2},
  ['Où vérifier que tu te connectes au vrai site de ton ENT ?','dans la barre d’adresse du navigateur',['dans le titre de l’onglet seulement','sur un message reçu','dans la couleur du site'],'L’adresse doit être celle communiquée par le collège.',3]]),2],
  [d=>{const n=R(3,8);return num(`Tu as ${n} comptes importants. Combien de mots de passe différents faut-il idéalement ?`,n,{expl:`Un mot de passe différent par compte : <b>${n}</b> (un gestionnaire de mots de passe peut aider à les retenir).`,hint:'Un par compte.'});},1])},

{id:'pix6b',name:'Rechercher une information en ligne',icon:'🔎',domain:'Information et données',
 refs:[D1+', compétence 1.1 « Mener une recherche et une veille d’information »',NS],
 tip:'Avant de taper ta recherche, choisis 2 ou 3 mots-clés importants ; après, ouvre au moins deux sources différentes pour vérifier.',
 c:C(`Pour un exposé sur les volcans, tu tapes une question dans un moteur de recherche et obtiens des milliers de résultats. Lesquels choisir ? Bien chercher, c’est choisir ses <b>mots-clés</b>, comprendre la <b>page de résultats</b> et <b>vérifier</b> les sources.`,
  [T('Mots-clés et résultats',`<p>Un <b>moteur de recherche</b> (Qwant Junior, Google, Bing…) trouve des pages qui contiennent tes mots. On utilise des <b>mots-clés</b> précis : « volcan éruption Islande » plutôt que « je voudrais savoir comment marchent les volcans ».</p><p>La page de résultats montre pour chaque lien un titre, une adresse et un extrait. Les premiers résultats peuvent être des <b>annonces</b> (publicités) signalées par « Sponsorisé » ou « Annonce ».</p>`),
   T('Choisir et vérifier une source',`<p>On regarde <b>qui</b> publie (site officiel, encyclopédie, journal, blog personnel), <b>quand</b> (date de mise à jour), et on compare au moins deux sources. Un site institutionnel (.gouv.fr, musée, université) ou une encyclopédie relue est en général plus fiable qu’un forum.</p>`)],
  [{q:'Tu cherches la hauteur du mont Blanc. Comment faire ?',s:['Mots-clés : « hauteur mont Blanc ».','J’ouvre deux sources sérieuses (encyclopédie, site d’un organisme officiel).','Je compare : environ 4 806 m (la valeur varie légèrement selon les mesures).']}],
  ['Je choisis des mots-clés précis.','Je repère et j’évite les annonces publicitaires.','J’ouvre plusieurs sources et je vérifie leur auteur et leur date.','Je note la source de l’information que je garde.'],
  ['Taper une phrase entière avec des mots inutiles.','Cliquer sur le premier résultat sans vérifier que c’est une publicité.','Recopier une information sans vérifier ni citer la source.'],
  ['Mots-clés précis.','Annonce ≠ résultat naturel.','Vérifier auteur, date, et croiser deux sources.']),
 g:mix([bank([
  ['Pour un exposé sur les abeilles, quels mots-clés choisir ?','abeille pollinisation ruche',['je cherche des informations sur les abeilles s’il vous plaît','abeille','animaux'],'Des mots précis, sans mots inutiles.'],
  ['Dans une page de résultats, que signifie « Sponsorisé » ?','c’est une publicité payée',['c’est le meilleur résultat','c’est une source officielle','c’est un site de l’école'],'Les annonces sont payées pour apparaître en haut.'],
  ['Quelle source est en général la plus fiable pour une information de santé ?','un site officiel de santé publique',['un commentaire sur un réseau social','une vidéo sans auteur','une publicité'],'On privilégie les sources institutionnelles et identifiées.'],
  ['Pourquoi comparer au moins deux sources ?','pour vérifier que l’information est confirmée',['pour copier plus vite','parce que les moteurs l’exigent','pour avoir plus de publicités'],'Une seule source peut se tromper.'],
  ['Quel élément d’une page web aide à juger sa fiabilité ?','l’auteur et la date de publication',['la couleur du site','le nombre d’images','la taille du texte'],'Qui écrit, et quand ?'],
  ['Un moteur de recherche…','trouve des pages qui contiennent les mots demandés',['vérifie que les informations sont vraies','écrit les réponses à ta place','est un site d’encyclopédie'],'Il ne garantit pas la vérité des pages.'],
  ['Qwant Junior est…','un moteur de recherche adapté aux jeunes',['un réseau social','un jeu vidéo','un logiciel de dessin'],'Il filtre certains contenus.'],
  ['Tu trouves une information surprenante sur un seul blog. Tu…','cherches si d’autres sources sérieuses la confirment',['la publies tout de suite','la recopies dans ton exposé','la crois car elle est en ligne'],'Une information non confirmée peut être fausse.',2],
  ['Que faut-il noter quand on garde une information pour un exposé ?','la source (site, auteur, date)',['seulement le titre de l’exposé','le nombre de résultats','la couleur de la page'],'Citer ses sources est indispensable.',2],
  ['Une adresse web qui se termine par « gouv.fr » indique…','un site d’un service de l’État français',['un site de jeux','un site commercial','un réseau social'],'Domaine réservé aux administrations françaises.',2],
  {tf:'Tout ce qui apparaît en premier dans un moteur de recherche est forcément vrai.',v:false,e:'L’ordre dépend d’algorithmes et de publicités, pas de la vérité.'},
  ['Pour chercher une expression exacte comme « cycle de l’eau », on peut…','la mettre entre guillemets',['l’écrire en majuscules','ajouter beaucoup de points','la répéter trois fois'],'Les guillemets demandent l’expression exacte.',3]]),3])},

{id:'pix6c',name:'Organiser fichiers et dossiers',icon:'🗂️',domain:'Environnement numérique',
 refs:[D5+', compétence 5.2 « Évoluer dans un environnement numérique »',D1+', compétence 1.2 « Gérer des données »',NS],
 tip:'Un nom de fichier utile dit QUOI et QUAND : « Histoire_Romains_2026-10-12.odt » se retrouve facilement, « doc1.odt » non.',
 c:C(`Ton exposé est quelque part sur l’ordinateur… mais où ? Pour retrouver ses travaux, on les range dans des <b>dossiers</b> bien nommés, comme des classeurs, et on donne aux <b>fichiers</b> des noms clairs.`,
  [T('Fichiers, dossiers, extensions',`<p>Un <b>fichier</b> contient un document (texte, image, son…). Son <b>extension</b>, après le point du nom, indique son type : expose.odt ou expose.docx (texte), expose.pdf (document à consulter), photo.png ou photo.jpg (image), chanson.mp3 (son), film.mp4 (vidéo).</p><p>Un <b>dossier</b> (répertoire) regroupe des fichiers et d’autres dossiers : on obtient une <b>arborescence</b> (Documents › 6e › Histoire › Exposé).</p>`),
   T('Bien ranger',`<p>On crée un dossier par matière, puis par thème. On nomme les fichiers sans espaces ni caractères spéciaux, avec la date si utile. On peut <b>copier</b>, <b>déplacer</b>, <b>renommer</b> et <b>supprimer</b> (la corbeille permet de récupérer un fichier supprimé par erreur).</p><p>On enregistre régulièrement (Ctrl + S) et on fait une copie de sauvegarde des travaux importants.</p>`)],
  [{q:'Où ranger l’exposé d’histoire sur les Romains ?',s:['Ouvrir le dossier Documents, puis 6e.','Créer (ou ouvrir) le dossier Histoire.','Enregistrer le fichier sous « Histoire_Romains_exposé.odt ».']}],
  ['Je crée une arborescence simple (matière › thème).','Je donne un nom clair à chaque fichier.','J’enregistre régulièrement.','Je garde une copie de sauvegarde des travaux importants.'],
  ['Tout enregistrer sur le bureau avec des noms comme « doc1 ».','Confondre copier (deux exemplaires) et déplacer (un seul).','Vider la corbeille sans vérifier.'],
  ['Extension = type de fichier.','Dossiers = arborescence de rangement.','Noms clairs et sauvegardes régulières.']),
 g:mix([pairs([['travail.odt','un document texte'],['travail.pdf','un document à consulter ou imprimer'],['travail.png','une image'],['travail.mp3','un fichier son'],['travail.mp4','une vidéo'],['travail.ods','une feuille de tableur']],{q:'Le fichier « %s » est…',rq:'Quel fichier est %s ?'}),2],
  [bank([
   ['Quel nom de fichier est le plus utile ?','SVT_cellules_2026-10-12.odt',['doc1.odt','sans titre.odt','truc final final.odt'],'Il dit la matière, le sujet et la date.'],
   ['Que fait « copier-coller » d’un fichier ?','il crée un deuxième exemplaire',['il déplace le fichier sans en garder une copie','il supprime le fichier','il change son extension'],'L’original reste à sa place.'],
   ['Que fait « couper-coller » d’un fichier ?','il le déplace',['il le duplique','il l’efface définitivement','il le renomme'],'Le fichier n’est plus à l’ancien emplacement.'],
   ['Où va un fichier supprimé en général ?','dans la corbeille',['sur Internet','dans un nouveau dossier','nulle part, il disparaît toujours'],'On peut encore le restaurer tant que la corbeille n’est pas vidée.'],
   ['Une arborescence, c’est…','l’organisation des dossiers emboîtés',['un logiciel de dessin','un type d’image','un virus'],'Comme des tiroirs dans des tiroirs.'],
   ['Quel raccourci clavier enregistre souvent un document ?','Ctrl + S',['Ctrl + P','Ctrl + Z','Alt + F4'],'S comme « save » (enregistrer).',2],
   ['Pourquoi éviter les espaces et les accents dans les noms de fichiers ?','certains systèmes ou sites les gèrent mal',['c’est interdit par la loi','le fichier devient plus lourd','le fichier s’efface'],'Cela évite des erreurs lors des envois.',2],
   {tf:'Renommer un fichier change son contenu.',v:false,e:'Seul le nom change.'},
   ['Pour retrouver un travail important si l’ordinateur tombe en panne, il faut…','en avoir une copie de sauvegarde ailleurs',['l’imprimer seulement','le mettre sur le bureau','changer son extension'],'La sauvegarde protège contre les pertes.',3]]),2])},

{id:'pix6d',name:'Communiquer avec une messagerie',icon:'✉️',domain:'Communication',
 refs:[D2+', compétence 2.1 « Interagir »',NS],
 tip:'Avant d’envoyer : un objet clair, une formule de politesse, un message relu, la bonne personne en destinataire… et pas de message écrit sous le coup de la colère.',
 c:C(`Écrire à un professeur sur la messagerie de l’ENT n’est pas comme envoyer un message à un copain. Un courriel a des règles : un <b>objet</b>, un <b>destinataire</b>, une <b>formule de politesse</b>, un ton adapté.`,
  [T('Les éléments d’un courriel',`<p><b>À</b> : le destinataire principal. <b>Cc</b> (copie) : d’autres personnes informées. <b>Objet</b> : le sujet en quelques mots. Le <b>corps</b> du message commence par une formule (« Bonjour Madame, ») et finit par une formule et une signature.</p><p>Une <b>pièce jointe</b> est un fichier envoyé avec le message (attention à sa taille).</p>`),
   T('Bien se comporter en ligne',`<p>On reste poli, on relit avant d’envoyer, on n’écrit pas tout en majuscules (cela donne l’impression de crier). On ne transfère pas un message privé sans accord. On n’ouvre pas une pièce jointe d’un expéditeur inconnu.</p><p>Si un message est blessant ou menaçant, on ne répond pas, on garde une trace et on en parle à un adulte (3018 pour le cyberharcèlement).</p>`)],
  [{q:'Tu as été absent et tu veux le travail de mathématiques. Rédige un message.',s:['Objet : « Absence du 12 octobre – travail de mathématiques ».','« Bonjour Monsieur, j’étais absent le 12 octobre. Pourriez-vous m’indiquer le travail à faire ? »','« Merci beaucoup, bonne journée. Léo Martin, 6e B. »']}],
  ['Je choisis le bon destinataire.','J’écris un objet clair.','Je rédige poliment et je relis.','Je vérifie la pièce jointe avant d’envoyer.'],
  ['Laisser l’objet vide.','Écrire au professeur comme à un camarade (« Salut, c’est quoi les devoirs ? »).','Ouvrir une pièce jointe d’un inconnu.'],
  ['À, Cc, Objet, corps, signature.','Politesse et relecture.','Message blessant : ne pas répondre, garder une trace, en parler.']),
 g:mix([bank([
  {tf:'On peut écrire à un professeur avec des abréviations de SMS (« slt, c koi les devoirs »).',v:false,e:'On adopte un langage correct et poli.'},
  ['Tu veux envoyer ton exposé à ton professeur. Tu l’ajoutes…','en pièce jointe',['dans l’objet','dans le champ Cc','dans la signature'],'Le fichier accompagne le message.'],
  ['Avant d’envoyer un message en colère, il vaut mieux…','attendre, relire et se calmer',['l’envoyer tout de suite','l’écrire en majuscules','l’envoyer à toute la classe'],'Un message envoyé ne se rattrape pas.',2],
  ['Le champ « À » d’un courriel contient…','l’adresse du destinataire principal',['le sujet du message','la pièce jointe','la date'],'C’est la personne à qui on écrit.'],
  ['Quel objet de message est le plus clair ?','Absence du 12/10 – travail de maths',['Bonjour','Question','!!!'],'L’objet résume le sujet.'],
  ['Comment commencer un message à un professeur ?','Bonjour Madame,',['Salut !','Coucou','Yo'],'On utilise une formule de politesse adaptée.'],
  ['Écrire tout un message EN MAJUSCULES donne l’impression…','de crier',['d’être poli','d’être pressé','d’écrire mieux'],'C’est considéré comme agressif en ligne.'],
  ['Que signifie « Cc » ?','copie : d’autres destinataires sont informés',['message confidentiel','courrier certifié','corbeille'],'Ils reçoivent le même message.'],
  ['Tu reçois un message d’un inconnu avec une pièce jointe « cadeau.exe ». Que fais-tu ?','je ne l’ouvre pas et je préviens un adulte',['je l’ouvre pour voir','je le transfère à mes amis','je réponds pour remercier'],'Une pièce jointe inconnue peut contenir un logiciel malveillant.'],
  ['Une pièce jointe est…','un fichier envoyé avec le message',['la signature du message','le destinataire','l’objet du message'],'Exemple : un exposé en PDF.'],
  ['Tu reçois un message insultant. Que fais-tu ?','je ne réponds pas, je garde une trace et j’en parle à un adulte',['je réponds encore plus méchamment','je supprime tout immédiatement','je le transfère à toute la classe'],'Il faut des preuves et de l’aide.'],
  ['Quel numéro gratuit aide en cas de cyberharcèlement ?','3018',['112','18','3919'],'Le 3018 est le numéro national contre le cyberharcèlement.',2],
  ['Peut-on transférer à d’autres un message privé reçu d’un ami ?','seulement avec son accord',['oui, toujours','oui, si c’est drôle','oui, s’il est court'],'Respecter la vie privée de l’expéditeur.',2],
  {tf:'Il faut relire un message avant de l’envoyer.',v:true,e:'On corrige les erreurs et le ton.'},
  ['Que mettre à la fin d’un message à un professeur ?','une formule de politesse et son nom avec sa classe',['rien','un émoji seulement','son mot de passe'],'Le professeur sait qui écrit.',3]]),3])},

{id:'pix6e',name:'Créer un document simple',icon:'📝',domain:'Création de contenu',
 refs:[D3+', compétence 3.1 « Développer des documents textuels »',NS],
 tip:'Utilise les styles (Titre 1, Titre 2, Corps de texte) plutôt que de grossir le texte à la main : ton document sera clair et facile à modifier.',
 c:C(`Rendre un exposé tapé à l’ordinateur, c’est plus que taper du texte : il faut un <b>titre</b>, des <b>paragraphes</b>, peut-être une <b>image</b> légendée, et une présentation lisible. Un <b>traitement de texte</b> (LibreOffice Writer, Word…) le permet.`,
  [T('Saisir et mettre en forme',`<p>On distingue la <b>saisie</b> (taper le texte) et la <b>mise en forme</b> : police, taille, gras, italique, souligné, couleur, alignement (gauche, centré, justifié).</p><p>Les <b>styles</b> (Titre 1, Titre 2…) appliquent une mise en forme cohérente à tous les titres. Le retour à la ligne crée un nouveau paragraphe.</p>`),
   T('Images, vérification, enregistrement',`<p>On peut insérer une image (avec sa source et une légende), un tableau, une liste à puces. Le correcteur souligne les fautes probables, mais il ne remplace pas la relecture.</p><p>On enregistre au format du logiciel (odt pour LibreOffice, docx pour Word) pour pouvoir modifier, et on exporte en <b>PDF</b> pour rendre une version fixe.</p>`)],
  [{q:'Mettre en page un exposé d’une page.',s:['Appliquer le style « Titre 1 » au titre.','Taper le texte en paragraphes courts ; insérer une image avec légende et source.','Relire, puis exporter en PDF pour le rendre.']}],
  ['Je tape d’abord le texte.','J’applique les styles aux titres.','J’insère images et légendes (avec source).','Je relis, j’enregistre et j’exporte en PDF.'],
  ['Mettre en forme avec des espaces et des retours à la ligne répétés.','Faire confiance au correcteur sans relire.','Oublier la source d’une image.'],
  ['Saisie ≠ mise en forme.','Styles pour les titres.','PDF pour rendre une version fixe.']),
 g:mix([bank([
  ['Quelle touche permet d’annuler la dernière action (avec Ctrl) ?','Z',['S','P','C'],'Ctrl + Z annule la dernière modification.',2],
  ['Pour garder un document modifiable, on l’enregistre…','au format du logiciel (odt ou docx)',['seulement en PDF','en image','en MP3'],'Le PDF sert à diffuser une version fixe.'],
  ['Un texte « justifié » est…','aligné à la fois à gauche et à droite',['écrit en gras','centré','souligné'],'Les lignes ont toutes la même largeur.',2],
  ['Sous une image insérée dans un exposé, on écrit…','une légende et la source',['son poids en Mo','le mot « image »','rien du tout'],'La légende explique, la source crédite l’auteur.'],
  ['Quel format est conseillé pour rendre un document qui ne doit plus être modifié ?','PDF',['ODT','TXT','MP3'],'Le PDF conserve la mise en page.'],
  ['À quoi servent les styles « Titre 1 », « Titre 2 » ?','à mettre en forme tous les titres de façon cohérente',['à corriger l’orthographe','à insérer des images','à enregistrer le fichier'],'Changer le style modifie tous les titres d’un coup.'],
  ['Quel alignement place le texte au milieu de la ligne ?','centré',['justifié','à gauche','à droite'],'On centre souvent les titres.'],
  ['Le correcteur orthographique…','signale des erreurs probables mais ne remplace pas la relecture',['corrige toutes les fautes','vérifie que les informations sont vraies','traduit le texte'],'Il laisse passer des erreurs (homophones…).'],
  ['Quand on insère une image trouvée en ligne, on doit…','indiquer sa source',['la déformer','la mettre en arrière-plan','changer son nom'],'Respect des auteurs.'],
  ['Pour faire une liste de matériel, on utilise…','une liste à puces',['un tableau de calcul','une image','une note de bas de page'],'Chaque élément sur une ligne précédée d’une puce.'],
  ['Quel logiciel est un traitement de texte libre ?','LibreOffice Writer',['LibreOffice Calc','Scratch','GIMP'],'Calc est un tableur, GIMP un logiciel d’image.',2],
  ['Mettre un mot en gras sert à…','le faire ressortir',['le supprimer','le traduire','le cacher'],'On met en valeur les mots importants.'],
  {tf:'Appuyer plusieurs fois sur Entrée est la bonne façon de passer à une nouvelle page.',v:false,e:'On utilise un saut de page.',d:2},
  ['Un « saut de page » permet…','de commencer la suite du texte sur une nouvelle page',['de supprimer une page','d’imprimer','de changer de police'],'Plus fiable que des retours à la ligne.',3]]),2])},

{id:'pix6f',name:'Protéger mots de passe et données personnelles',icon:'🛡️',domain:'Protection et sécurité',
 refs:[D4+', compétences 4.1 « Sécuriser l’environnement numérique » et 4.2 « Protéger les données personnelles et la vie privée »',NS+' (parcours de 6e consacré au domaine 4 et au cyberharcèlement)'],
 tip:'Un bon mot de passe est LONG (12 caractères ou plus) : une phrase de passe comme « Velo-Bleu-Pluie-Marche » est facile à retenir et difficile à deviner.',
 c:C(`Ton nom, ton adresse, ta photo, ton numéro de téléphone, ta date de naissance : ce sont des <b>données personnelles</b>. Sur Internet, elles peuvent être copiées et réutilisées. Les protéger, c’est d’abord choisir de bons <b>mots de passe</b> et réfléchir avant de publier.`,
  [T('Mots de passe robustes',`<p>Un mot de passe <b>robuste</b> est long (au moins 12 caractères), mélange minuscules, majuscules, chiffres et symboles, et ne contient pas d’information facile à deviner (prénom, date de naissance, nom du chien).</p><p>La <b>phrase de passe</b> (plusieurs mots séparés) est une bonne méthode. On ne le note pas sur un post-it collé à l’écran.</p>`),
   T('Données personnelles',`<p>Une donnée personnelle permet d’identifier une personne : nom, adresse, photo, numéro, adresse électronique, localisation… On n’en publie pas sur soi sans réfléchir, et jamais sur les autres sans leur accord.</p><p>On règle ses comptes en mode <b>privé</b>. Le <b>RGPD</b> (règlement européen de 2018) protège ces données et donne des droits (accès, effacement).</p>`)],
  [{q:'Juliette veut un mot de passe pour son compte Pix. Elle hésite entre « Juliette2014 » et « Ch@t-Vert-Nuage-71! ». Lequel choisir ?',s:['« Juliette2014 » contient son prénom et une année : facile à deviner.','« Ch@t-Vert-Nuage-71! » est long et varié.','Elle choisit la phrase de passe et ne la donne à personne.']}],
  ['Je choisis un mot de passe long (phrase de passe).','Je n’y mets ni prénom, ni date, ni mot évident.','Je le garde secret et différent pour chaque compte.','Je réfléchis avant de publier une donnée personnelle.'],
  ['Utiliser « 123456 » ou « azerty ».','Publier son adresse ou son emploi du temps.','Publier la photo d’un camarade sans son accord.'],
  ['Mot de passe : long, varié, secret, unique.','Donnée personnelle : tout ce qui identifie quelqu’un.','Pas de publication sur les autres sans accord.']),
 g:mix([d=>{const [pw,why]=P(PWD);const strong=why.startsWith('robuste');return ch(`Le mot de passe « <b>${pw}</b> » est-il robuste ?`,strong?'Oui':'Non',[strong?'Non':'Oui'],{expl:`Il est ${why}.`,hint:'Longueur, variété, imprévisibilité.'});},3],
  [bank([
   ['Laquelle de ces informations est une donnée personnelle ?','mon adresse',['la capitale de la France','la météo de demain','le nom d’un fleuve'],'Elle permet de m’identifier ou de me localiser.'],
   ['Quel mot de passe est le plus robuste ?','Velo-Bleu-Pluie-Marche',['Lucas2013','motdepasse','azerty'],'Une phrase de passe longue.'],
   ['Où ne faut-il PAS noter son mot de passe ?','sur un post-it collé à l’écran',['nulle part, je le retiens','dans un gestionnaire de mots de passe sécurisé','dans ma mémoire'],'Tout le monde pourrait le lire.'],
   ['Peut-on publier la photo d’un camarade sans lui demander ?','non',['oui, si elle est jolie','oui, sur un compte privé','oui, s’il est absent'],'Chacun a droit à son image.'],
   ['Que signifie régler son compte en « privé » ?','seules les personnes acceptées voient mes publications',['mon compte est supprimé','tout le monde voit tout','je ne peux plus rien publier'],'On limite qui voit ses contenus.'],
   ['Le RGPD est…','un règlement européen qui protège les données personnelles',['un logiciel antivirus','un réseau social','un mot de passe très long'],'Entré en application en 2018.',2],
   ['Un inconnu en ligne te demande ton adresse et ton numéro. Tu…','refuses et tu en parles à un adulte',['réponds pour être poli','donnes seulement l’adresse','donnes un faux numéro et ton adresse'],'Ne jamais donner ses coordonnées à un inconnu.'],
   ['Ta date de naissance dans un mot de passe…','le rend facile à deviner',['le rend plus sûr','est obligatoire','ne change rien'],'C’est une information souvent connue.'],
   {tf:'Une phrase de passe longue peut être à la fois facile à retenir et robuste.',v:true,e:'C’est tout l’intérêt de la phrase de passe.'},
   ['Pourquoi éviter de publier ton emploi du temps et ta position ?','quelqu’un pourrait savoir où te trouver',['cela ralentit Internet','c’est interdit aux adultes','cela efface tes photos'],'Ce sont des informations sensibles pour ta sécurité.',2]]),2])},

{id:'pix6g',name:'Comprendre les règles de base du droit numérique',icon:'⚖️',domain:'Citoyenneté numérique',
 refs:[D2+', compétence 2.2 « Partager et publier »',D4+', compétence 4.2',NS],
 tip:'Avant de publier : est-ce que j’ai le droit d’utiliser ce contenu (droit d’auteur) ? est-ce que la personne est d’accord (droit à l’image) ? est-ce que je dirais ça en face (respect) ?',
 c:C(`Internet n’est pas une zone sans loi. Les mêmes règles qu’ailleurs s’appliquent : respect des autres, <b>droit à l’image</b>, <b>droit d’auteur</b>, interdiction de harceler ou d’insulter. Les connaître, c’est se protéger et protéger les autres.`,
  [T('Droit à l’image et respect',`<p>Chacun a le <b>droit à l’image</b> : on ne publie pas la photo ou la vidéo de quelqu’un sans son accord (et celui de ses parents s’il est mineur).</p><p>Les insultes, menaces, moqueries répétées et rumeurs sont interdites en ligne comme ailleurs. Le <b>cyberharcèlement</b> est un délit. On peut le signaler (3018, plateformes, adultes du collège).</p>`),
   T('Droit d’auteur',`<p>Un texte, une image, une musique, une vidéo appartiennent à leur auteur : on ne peut pas les copier et les republier comme si c’étaient les nôtres. On cite toujours ses sources et on utilise des contenus dont la <b>licence</b> autorise la réutilisation (par exemple certaines licences Creative Commons).</p>`)],
  [{q:'Hugo veut publier une vidéo de la classe filmée en récréation. Que doit-il vérifier ?',s:['Les personnes filmées sont-elles d’accord ?','Pour des mineurs, l’accord des parents est aussi nécessaire.','Sans accord, il ne publie pas (droit à l’image).']}],
  ['Je vérifie l’accord des personnes avant de publier une image.','Je vérifie que j’ai le droit d’utiliser un contenu (auteur, licence).','Je cite mes sources.','En cas de harcèlement, je ne participe pas, je signale et j’en parle.'],
  ['Croire que ce qui est en ligne est libre de droits.','Partager une moquerie « pour rire » : on devient complice.','Publier une photo de groupe sans demander.'],
  ['Droit à l’image : accord obligatoire.','Droit d’auteur : citer, respecter la licence.','Cyberharcèlement : délit, 3018.']),
 g:mix([bank([
  ['Recopier un texte trouvé en ligne et le présenter comme le sien s’appelle…','du plagiat',['une citation','une source','une licence'],'Citer l’auteur permet d’éviter le plagiat.'],
  ['Tu filmes un professeur en classe sans autorisation et tu publies la vidéo. C’est…','interdit : atteinte au droit à l’image',['autorisé si c’est drôle','autorisé si le compte est privé','autorisé si on floute le décor'],'Il faut l’accord de la personne filmée.'],
  {tf:'Un mineur doit avoir l’accord de ses parents pour la publication de son image.',v:true,e:'Les parents exercent ce droit pour leur enfant mineur.',d:2},
  ['Que signifie le symbole © ?','l’œuvre est protégée par le droit d’auteur (copyright)',['l’œuvre est gratuite','l’œuvre est un virus','l’œuvre est publique'],'Copyright = droits réservés.',2],
  ['Peut-on publier en ligne une photo de ses amis sans leur accord ?','non',['oui, s’ils sont souriants','oui, si le compte est privé','oui, si la photo est floue'],'Le droit à l’image impose leur accord.'],
  ['Une image trouvée sur Internet est-elle libre d’utilisation ?','pas forcément, car elle a un auteur et une licence',['oui, toujours','oui, si elle est belle','oui, si on la recadre'],'Il faut vérifier les droits.'],
  ['Que doit-on faire quand on utilise le texte d’un autre dans un exposé ?','citer l’auteur et la source',['le modifier légèrement','le recopier sans rien dire','le traduire'],'Sinon, c’est du plagiat.'],
  ['Partager une moquerie sur un camarade « pour rire »…','participe au harcèlement',['n’a aucune conséquence','est autorisé si c’est drôle','est un droit'],'On devient complice.'],
  ['Le cyberharcèlement est…','un délit puni par la loi',['une blague','autorisé sur les réseaux sociaux','une simple erreur'],'La loi le sanctionne.'],
  ['Qui contacter en cas de cyberharcèlement ?','le 3018 et un adulte de confiance',['personne','le harceleur','toute la classe'],'Le 3018 est gratuit et anonyme.'],
  ['Le droit d’auteur protège…','les œuvres (textes, images, musiques, vidéos)',['seulement les livres','seulement les films','les mots de passe'],'Toutes les créations originales.'],
  ['Une licence Creative Commons…','indique comment on peut réutiliser une œuvre',['interdit toute utilisation','est un antivirus','est un réseau social'],'Elle précise les conditions de réutilisation.',2],
  {tf:'Les règles de la loi s’appliquent aussi sur Internet.',v:true,e:'Internet n’est pas une zone de non-droit.'},
  ['Quelqu’un publie une rumeur sur toi. Que fais-tu ?','je fais des captures d’écran et j’en parle à un adulte',['je publie une rumeur sur lui','je ne dis rien','je supprime mon compte sans rien dire'],'Garder des preuves et se faire aider.',2]]),2])},

{id:'pix6h',name:'Premiers repères Pix et auto-évaluation',icon:'🎯',domain:'Pix',
 refs:[NS+' : attestation de sensibilisation au numérique en fin de 6e (deux parcours, au moins 50 % de réussite à chacun) ; '+CRCN],
 tip:'Sur Pix, une erreur n’est pas grave : les questions s’adaptent à ton niveau. Lis bien la consigne et utilise les outils proposés (recherche, tutoriels).',
 c:C(`En 6e, tous les élèves passent sur la plateforme <b>Pix</b> deux parcours qui permettent d’obtenir l’<b>attestation de sensibilisation au numérique</b>, remise en fin d’année. C’est le début d’un parcours qui mène à la certification Pix en 3e.`,
  [T('Le CRCN et Pix',`<p>Le <b>cadre de référence des compétences numériques</b> (CRCN) comprend <b>5 domaines</b> : information et données ; communication et collaboration ; création de contenus ; protection et sécurité ; environnement numérique. Ils regroupent <b>16 compétences</b>, chacune avec <b>8 niveaux</b>.</p><p><b>Pix</b> est la plateforme publique qui évalue, aide à développer et certifie ces compétences.</p>`),
   T('L’attestation de 6e',`<p>Elle est délivrée si l’élève obtient au moins <b>50 %</b> de réussite à chacun des deux parcours : un parcours sur le domaine 4 « Protection et sécurité » (avec le cyberharcèlement) et un parcours d’<b>initiation</b> aux domaines 1, 2, 3 et 5. Un troisième parcours, facultatif, permet de la rattraper. Elle est mentionnée dans le livret scolaire.</p><p>S’auto-évaluer : repérer ce que l’on sait faire et ce qu’on doit retravailler.</p>`)],
  [{q:'Après un parcours Pix, Nina voit qu’elle a 40 % sur « Protection et sécurité ». Que faire ?',s:['Repérer les questions ratées (mots de passe ? données personnelles ?).','Revoir ces notions avec les tutoriels proposés.','Refaire les épreuves non réussies (parcours de rattrapage) pour atteindre 50 %.']}],
  ['Je lis la consigne en entier.','J’utilise les outils autorisés (recherche, tutoriels).','Après le parcours, je regarde mes résultats par compétence.','Je retravaille les compétences les plus faibles.'],
  ['Répondre au hasard pour aller vite.','Croire qu’une erreur fait perdre toute la note : Pix s’adapte.','Demander les réponses à un camarade pendant le parcours.'],
  ['CRCN : 5 domaines, 16 compétences, 8 niveaux.','Attestation de 6e : 2 parcours, ≥ 50 % à chacun.','Certification Pix en 3e.']),
 g:mix([bank([
  ['Combien de domaines compte le CRCN ?','5',['3','16','8'],'Information, communication, création, protection, environnement.'],
  ['Combien de compétences compte le CRCN ?','16',['5','8','32'],'Réparties dans 5 domaines.'],
  ['Combien de niveaux de maîtrise sont définis pour chaque compétence ?','8',['5','3','16'],'De novice à expert.',2],
  ['Quand la certification Pix est-elle obligatoire au collège ?','en 3e',['en 6e','en 5e','jamais'],'En fin de cycle 4.'],
  ['Que reçoit-on en fin de 6e après les parcours Pix réussis ?','une attestation de sensibilisation au numérique',['le brevet','un permis de conduire','une note de maths'],'Elle est inscrite au livret scolaire.'],
  ['Quel pourcentage de réussite faut-il à chaque parcours pour obtenir l’attestation de 6e ?','au moins 50 %',['100 %','au moins 90 %','au moins 10 %'],'Sinon, un parcours de rattrapage est possible.',2],
  ['Sur quel domaine porte l’un des deux parcours de l’attestation de 6e ?','protection et sécurité (avec le cyberharcèlement)',['programmation de jeux','tableur avancé','montage vidéo'],'Domaine 4 du CRCN.',2],
  ['Pix est…','la plateforme publique d’évaluation et de certification des compétences numériques',['un réseau social','un moteur de recherche','un jeu vidéo commercial'],'Service public (groupement d’intérêt public).'],
  pairs([['Information et données','domaine 1'],['Communication et collaboration','domaine 2'],['Création de contenus','domaine 3'],['Protection et sécurité','domaine 4'],['Environnement numérique','domaine 5']],{q:'« %s » est…',rq:'Quel est le nom du %s du CRCN ?'}),
  {tf:'Sur Pix, les questions s’adaptent au niveau de l’élève.',v:true,e:'Le niveau des épreuves évolue selon les réponses.'}]),2])}
]);

MQ.add('pix','5',[
{id:'pix5a',name:'Évaluer la fiabilité d’une information',icon:'🧐',domain:'Information et données',
 refs:[D1+', compétence 1.1 « Mener une recherche et une veille d’information »',CRCN],
 tip:'Trois questions avant de croire ou partager : QUI le dit ? QUAND ? Est-ce CONFIRMÉ par une autre source sérieuse ?',
 c:C(`Une image choquante circule, une « info » incroyable est partagée des milliers de fois… Est-ce vrai ? Sur Internet, n’importe qui peut publier. Savoir <b>évaluer une information</b>, c’est éviter de se faire manipuler et de propager des <b>infox</b> (fausses informations).`,
  [T('Les critères de fiabilité',`<p><b>L’auteur</b> : est-il identifié ? compétent sur le sujet ? (journaliste, scientifique, institution). <b>La date</b> : l’information est-elle récente ? <b>Les sources</b> : l’article cite-t-il d’où viennent les chiffres ? <b>Le ton</b> : un titre sensationnel (« INCROYABLE ! ») et des fautes nombreuses doivent alerter.</p><p>On <b>recoupe</b> : une information sérieuse est reprise par plusieurs médias indépendants.</p>`),
   T('Infox, rumeurs et images trompeuses',`<p>Une <b>infox</b> (fake news) est une fausse information diffusée volontairement ou par erreur. Une image peut être retouchée, sortie de son contexte (photo ancienne présentée comme récente) ou générée par une IA.</p><p>Outils : la <b>recherche d’image inversée</b> retrouve l’origine d’une photo ; les rubriques de vérification des médias (fact-checking) analysent les rumeurs. On distingue aussi <b>information</b>, <b>opinion</b> et <b>publicité</b>.</p>`)],
  [{q:'Une photo d’un requin nageant sur une autoroute inondée circule après une tempête. Que faire ?',s:['Faire une recherche d’image inversée : la photo existe déjà depuis plusieurs années, c’est un montage.','Chercher si des médias fiables en parlent : aucun ne confirme.','Conclusion : ne pas partager ; c’est une infox récurrente.']}],
  ['J’identifie l’auteur et le type de site.','Je vérifie la date.','Je recoupe avec d’autres sources indépendantes.','Je me méfie des titres sensationnels et des images sans origine.'],
  ['Partager avant de vérifier.','Croire une information parce qu’elle a beaucoup de « j’aime ».','Confondre un article d’opinion avec une information vérifiée.'],
  ['Qui ? Quand ? Confirmé ?','Infox : fausse information.','Recherche d’image inversée, fact-checking.']),
 g:mix([bank([
  ['Quel indice doit te rendre méfiant face à un article ?','un titre sensationnel sans auteur ni source',['un auteur identifié','une date récente','des sources citées'],'Le sensationnalisme vise à faire cliquer.'],
  ['Que signifie « recouper » une information ?','vérifier qu’elle est donnée par plusieurs sources indépendantes',['la couper en morceaux','la partager plusieurs fois','la traduire'],'Plusieurs sources sérieuses = plus fiable.'],
  ['Une infox est…','une fausse information',['une information officielle','un logiciel','une publicité'],'De l’anglais « fake news ».'],
  ['Comment retrouver l’origine d’une photo ?','avec une recherche d’image inversée',['en l’agrandissant','en changeant sa couleur','en comptant les « j’aime »'],'Le moteur cherche où l’image a déjà été publiée.'],
  ['Une information partagée 100 000 fois est-elle forcément vraie ?','non',['oui','oui, si elle est récente','oui, si elle a une image'],'La popularité ne prouve rien.'],
  ['Quel site est le plus fiable pour une information scientifique ?','le site d’un organisme de recherche',['un forum anonyme','une vidéo virale sans source','un compte parodique'],'Les institutions de recherche sont identifiées et responsables.'],
  ['« À mon avis, ce film est nul » est…','une opinion',['une information vérifiée','une publicité','une infox'],'C’est un avis personnel.'],
  ['« Le film est sorti le 3 mai » est…','une information vérifiable',['une opinion','une rumeur','une publicité'],'On peut la vérifier.'],
  ['Une photo de 2015 présentée comme prise hier est…','sortie de son contexte',['parfaitement fiable','une opinion','une publicité'],'L’image est vraie mais trompe sur la date.',2],
  ['À quoi sert une rubrique de « fact-checking » dans un média ?','à vérifier des affirmations et rumeurs',['à vendre des produits','à publier des jeux','à donner la météo'],'Elle analyse le vrai et le faux.',2],
  ['Un compte qui imite un journal connu avec un nom légèrement différent…','peut diffuser de fausses informations',['est toujours le vrai journal','est forcément officiel','est un antivirus'],'Vérifier l’adresse et le nom exact.',2],
  ['Une image peut-elle être créée de toutes pièces par une intelligence artificielle ?','oui',['non, jamais','seulement en noir et blanc','seulement par un journal'],'Il faut vérifier sa source.',2],
  {tf:'Un article sans auteur ni date est moins fiable qu’un article signé et daté.',v:true,e:'On ne peut ni identifier ni dater la source.'},
  {tf:'Si un ami partage une information, elle est forcément vraie.',v:false,e:'Ton ami peut s’être trompé.'},
  ['Pourquoi les infox circulent-elles vite ?','elles provoquent des émotions fortes et sont partagées sans vérification',['elles sont plus courtes','elles sont gratuites','elles sont écrites par des robots seulement'],'L’émotion pousse au partage.',3],
  ['Sur une page, la mention « Publicité » ou « Contenu sponsorisé » indique…','un contenu payé par une marque',['un article de journaliste indépendant','une information officielle','un avis de lecteur'],'Il faut la distinguer de l’information.',3]]),1])},

{id:'pix5b',name:'Lire et organiser des données simples',icon:'📊',domain:'Information et données',
 refs:[D1+', compétences 1.2 « Gérer des données » et 1.3 « Traiter des données »',CRCN],
 tip:'Dans un tableau, une ligne = un élément (un élève, un jour), une colonne = une information (nom, âge, note). Un titre clair pour chaque colonne !',
 c:C(`Résultats d’un sondage, températures de la semaine, scores d’un tournoi : ce sont des <b>données</b>. Bien organisées dans un <b>tableau</b>, on peut les trier, les filtrer, les représenter par un graphique et en tirer des informations.`,
  [T('Tableau de données',`<p>Un tableau de données a des <b>lignes</b> (une par élément observé) et des <b>colonnes</b> (une par caractéristique), avec un <b>en-tête</b> qui nomme chaque colonne. Dans un tableur, chaque case est une <b>cellule</b> repérée par sa colonne (lettre) et sa ligne (numéro) : B3.</p>`),
   T('Trier, filtrer, représenter',`<p><b>Trier</b> : ranger les lignes (ordre croissant, décroissant, alphabétique). <b>Filtrer</b> : n’afficher que les lignes qui respectent une condition (classe = 5e B). On choisit un graphique adapté : <b>diagramme en barres</b> pour comparer, <b>diagramme circulaire</b> pour des parts d’un tout, <b>courbe</b> pour une évolution dans le temps.</p>`)],
  [{q:'Les températures de la semaine sont dans un tableur. Comment montrer leur évolution ?',s:['Colonne A : jours ; colonne B : températures (en °C).','Sélectionner les deux colonnes avec l’en-tête.','Insérer un graphique en courbe : l’évolution apparaît jour après jour.']}],
  ['Je mets un en-tête à chaque colonne.','Une ligne par élément, une colonne par information.','Je trie ou je filtre selon la question posée.','Je choisis un graphique adapté.'],
  ['Mélanger plusieurs informations dans une même cellule.','Trier une seule colonne : les lignes se mélangent.','Choisir un diagramme circulaire pour une évolution.'],
  ['Cellule = colonne + ligne (B3).','Trier ≠ filtrer.','Barres : comparer ; circulaire : parts ; courbe : évolution.']),
 g:mix([d=>{const cols='ABCDEFGH',c=P([...cols]),l=R(1,30);const bad=[cols[(cols.indexOf(c)+1)%8]+l,c+(l+1),l+c];return ch(`Dans un tableur, quelle cellule se trouve à la colonne ${c} et à la ligne ${l} ?`,c+l,bad,{expl:`On écrit d’abord la lettre de la colonne puis le numéro de la ligne : <b>${c}${l}</b>.`,hint:'Lettre puis numéro.'});},2],
  [d=>{const n=R(4,9);const v=Array.from({length:n},()=>R(8,20));const mx=Math.max(...v),mn=Math.min(...v);const ask=P(['plus grande','plus petite']);return num(`Voici les scores d’un jeu : ${v.join(' ; ')}. Après un tri décroissant, quelle est la ${ask==='plus grande'?'première':'dernière'} valeur ?`,ask==='plus grande'?mx:mn,{expl:`Un tri décroissant range de la plus grande à la plus petite : ${[...v].sort((a,b)=>b-a).join(' ; ')}.`,hint:'Décroissant : du plus grand au plus petit.'});},2],
  [sort({'Diagramme en barres':['comparer le nombre d’élèves par classe','comparer les ventes de quatre produits','comparer les tailles de cinq animaux'],'Diagramme circulaire':['montrer la part de chaque moyen de transport des élèves','montrer la répartition d’un budget','montrer les parts de votes'],'Courbe':['montrer l’évolution de la température sur une semaine','suivre sa taille d’année en année','suivre la population d’une ville depuis 1900']},{q:'Quel graphique choisir pour : %s ?'}),2],
  [bank([
   ['Dans un tableau de données, une colonne correspond à…','une caractéristique (nom, âge, note…)',['un élément observé','un graphique','un fichier'],'Les lignes, elles, correspondent aux éléments.'],
   ['Que fait un filtre dans un tableur ?','il n’affiche que les lignes qui respectent une condition',['il supprime le fichier','il change les couleurs','il calcule une moyenne'],'Les autres lignes sont cachées, pas supprimées.'],
   ['L’en-tête d’un tableau sert à…','nommer chaque colonne',['colorier les cellules','imprimer','trier'],'Il rend le tableau compréhensible.'],
   ['Trier par ordre alphabétique la colonne « Nom » range…','les lignes de A à Z selon le nom',['seulement les prénoms','les colonnes','les graphiques'],'Toutes les lignes suivent.',2],
   {tf:'Filtrer un tableau supprime définitivement les lignes masquées.',v:false,e:'Elles sont seulement cachées.',d:2},
   ['Quel graphique montre le mieux une évolution dans le temps ?','une courbe',['un diagramme circulaire','un tableau vide','une image'],'L’axe horizontal représente le temps.']]),3])},

{id:'pix5c',name:'Collaborer avec des outils numériques',icon:'🤝',domain:'Communication',
 refs:[D2+', compétences 2.3 « Collaborer » et 2.4 « S’insérer dans le monde numérique »',CRCN],
 tip:'Dans un document partagé, chacun a sa partie, on ne supprime pas le travail des autres et on utilise les commentaires pour discuter.',
 c:C(`Pour un exposé à quatre, inutile de s’envoyer douze versions par courriel : un <b>document partagé</b> (dans l’ENT, un pad, une suite bureautique en ligne) permet d’écrire ensemble, en même temps ou chacun à son tour.`,
  [T('Outils de collaboration',`<p>Document partagé, <b>espace de stockage</b> commun, <b>agenda</b> partagé, <b>forum</b> de classe, <b>visioconférence</b>. Les droits d’accès précisent qui peut <b>lire</b>, <b>commenter</b> ou <b>modifier</b>.</p><p>L’<b>historique des versions</b> permet de voir qui a modifié quoi, et de revenir à une version antérieure.</p>`),
   T('Règles de travail en groupe',`<p>Se répartir les tâches, respecter le travail des autres, utiliser les <b>commentaires</b> plutôt que de supprimer, signer ou colorer sa partie si demandé, fixer des échéances. On ne partage le lien d’un document qu’avec les personnes concernées.</p>`)],
  [{q:'Organiser un exposé à trois sur les énergies renouvelables.',s:['Créer un document partagé dans l’ENT et le partager aux deux camarades en modification.','Se répartir : solaire (Inès), éolien (Tom), hydraulique (Sami) ; une date limite.','Relire la partie des autres et laisser des commentaires ; l’historique garde toutes les versions.']}],
  ['Je partage le document avec les bons droits.','On se répartit les tâches et une échéance.','J’écris des commentaires au lieu d’effacer.','J’utilise l’historique si une erreur arrive.'],
  ['Supprimer la partie d’un camarade sans en parler.','Partager le lien publiquement.','Travailler chacun dans son fichier sans jamais fusionner.'],
  ['Droits : lire, commenter, modifier.','Historique des versions.','Répartition des tâches et respect du travail des autres.']),
 g:mix([bank([
  ['Quel outil permet d’écrire à plusieurs dans le même texte ?','un document partagé',['une clé USB','un courriel par personne','une imprimante'],'Tout le monde travaille sur la même version.'],
  ['Le droit « lecture seule » permet…','de lire sans modifier',['de tout modifier','de supprimer le document','de changer les droits'],'C’est le droit le plus limité.'],
  ['Tu n’es pas d’accord avec une phrase écrite par un camarade. Tu…','laisses un commentaire pour en discuter',['l’effaces sans rien dire','effaces toute sa partie','quittes le groupe'],'Le commentaire respecte son travail.'],
  ['À quoi sert l’historique des versions ?','voir les modifications et revenir à une version précédente',['imprimer le document','supprimer les commentaires','changer la police'],'Pratique après une erreur.'],
  ['Une visioconférence permet…','de se voir et se parler à distance',['de stocker des fichiers','de corriger l’orthographe','de faire un graphique'],'Avec caméra et micro.'],
  ['Avec qui partager le lien d’un document de groupe ?','seulement avec les membres du groupe et le professeur',['avec tout le monde sur un réseau social','avec des inconnus','avec personne, même pas le groupe'],'Pour protéger le travail et les données.'],
  ['Pour un travail de groupe, la première étape est…','se répartir les tâches et fixer une échéance',['écrire chacun la même partie','choisir la police','imprimer le document'],'Organisation d’abord.'],
  ['Un forum de classe sert à…','échanger des messages visibles par tout le groupe',['envoyer des messages secrets','stocker des vidéos','corriger les devoirs automatiquement'],'Chacun peut lire et répondre.'],
  ['Un agenda partagé permet…','de voir les échéances et rendez-vous communs',['d’écrire un exposé','de dessiner','de chiffrer ses messages'],'Utile pour s’organiser.'],
  ['Le droit « commentaire » permet…','de proposer des remarques sans modifier le texte',['de tout réécrire','de supprimer le fichier','d’inviter des inconnus'],'Intermédiaire entre lecture et modification.',2],
  {tf:'Dans un document partagé, on peut retrouver qui a écrit une partie grâce à l’historique.',v:true,e:'Chaque modification est enregistrée avec son auteur.',d:2},
  {tf:'En visioconférence, on peut enregistrer et diffuser les autres participants sans leur accord.',v:false,e:'Droit à l’image et à la vie privée.',d:2},
  ['Un camarade a effacé ta partie par erreur. Que faire ?','restaurer une version précédente grâce à l’historique',['tout réécrire de mémoire','supprimer le document','créer un nouveau compte'],'L’historique conserve les versions.',2],
  ['Pourquoi éviter de s’envoyer des versions par courriel pour écrire à plusieurs ?','on finit avec plusieurs versions différentes difficiles à fusionner',['les courriels sont interdits','les fichiers deviennent des virus','on ne peut pas joindre de fichier'],'Un document partagé garde une seule version à jour.',3]]),1])},

{id:'pix5d',name:'Mettre en forme un document structuré',icon:'📄',domain:'Création de contenu',
 refs:[D3+', compétence 3.1 « Développer des documents textuels »',CRCN],
 tip:'Structure d’abord (titres, sous-titres, paragraphes), décoration ensuite : avec les styles, la table des matières se fait toute seule.',
 c:C(`Un compte rendu de sortie, un exposé de 4 pages : pour être lisible, un document doit être <b>structuré</b>. Le traitement de texte offre des outils pour cela : styles de titres, table des matières, numéros de page, en-tête et pied de page, tableaux.`,
  [T('Styles et structure',`<p>Les <b>styles</b> de titre (Titre 1, Titre 2) créent une hiérarchie : grandes parties et sous-parties. Une <b>table des matières</b> se génère automatiquement à partir de ces styles. L’<b>en-tête</b> et le <b>pied de page</b> se répètent sur chaque page (nom, classe, numéro de page).</p>`),
   T('Tableaux, images, mise en page',`<p>Un <b>tableau</b> organise des informations en lignes et colonnes. Une image se positionne par rapport au texte (habillage) et porte une légende. On règle les <b>marges</b>, l’<b>orientation</b> (portrait ou paysage) et l’<b>interligne</b> pour un rendu aéré.</p>`)],
  [{q:'Structurer un compte rendu de sortie au musée.',s:['Titre 1 : « Sortie au musée » ; Titre 2 : « Le trajet », « Les œuvres », « Mon avis ».','Insérer la table des matières et les numéros de page dans le pied de page.','Ajouter un tableau des œuvres (titre, artiste, date) et une photo légendée.']}],
  ['J’applique les styles de titres.','J’insère la table des matières et la pagination.','J’ajoute tableaux et images légendées.','Je vérifie la mise en page (marges, orientation).'],
  ['Écrire les numéros de page à la main.','Grossir les titres manuellement : la table des matières ne les trouve pas.','Une image sans légende ni source.'],
  ['Styles → table des matières automatique.','En-tête et pied de page répétés.','Portrait ou paysage.']),
 g:mix([bank([
  ['Comment obtenir une table des matières automatique ?','en appliquant les styles de titres',['en écrivant les titres en gras','en soulignant les titres','en tapant les numéros à la main'],'Le logiciel repère les titres grâce aux styles.'],
  ['Le pied de page d’un document…','se répète en bas de chaque page',['n’apparaît que sur la première page','est un type d’image','est la dernière ligne du texte'],'On y met souvent le numéro de page.'],
  ['L’orientation « paysage » signifie que la page est…','plus large que haute',['plus haute que large','carrée','en couleur'],'Pratique pour un grand tableau.'],
  ['Pour présenter le nom, l’artiste et la date de plusieurs œuvres, on utilise…','un tableau',['un saut de page','une note de bas de page','un pied de page'],'Lignes = œuvres ; colonnes = informations.'],
  ['« Titre 2 » sert pour…','une sous-partie',['le titre du document','le corps du texte','la légende'],'Titre 1 : partie ; Titre 2 : sous-partie.'],
  ['L’interligne est…','l’espace entre les lignes',['l’espace entre les mots','la marge','la couleur du texte'],'Un interligne de 1,5 rend le texte plus aéré.'],
  ['L’habillage d’une image définit…','la façon dont le texte s’organise autour d’elle',['sa couleur','sa source','sa taille en Mo'],'Exemples : aligné sur le texte, encadré.',2],
  ['Les marges sont…','les espaces blancs autour du texte sur la page',['les titres','les colonnes d’un tableau','les images'],'Elles encadrent le contenu.'],
  ['Le numéro de page se met de préférence…','dans l’en-tête ou le pied de page grâce à un champ automatique',['à la main en bas de chaque page','dans le titre','dans une image'],'Il se met à jour tout seul.',2],
  {tf:'Si on ajoute une partie, la table des matières peut être mise à jour automatiquement.',v:true,e:'Il suffit de la mettre à jour.',d:2},
  ['Un document de quatre pages sans titres ni paragraphes est…','difficile à lire',['mieux structuré','plus court','plus facile à imprimer'],'La structure guide la lecture.'],
  {o:['Taper le texte','Appliquer les styles de titres','Insérer la table des matières','Exporter en PDF'],q:'Remets dans l’ordre les étapes pour produire le document :',e:'Texte → styles → table des matières → export.',d:2},
  ['Une note de bas de page sert à…','préciser une source ou expliquer un mot sans alourdir le texte',['numéroter les pages','ajouter une image','changer la marge'],'Un petit chiffre renvoie en bas de page.',3]]),1])},

{id:'pix5e',name:'Formats de fichiers et compatibilité',icon:'🧩',domain:'Environnement numérique',
 refs:[D5+', compétence 5.2 « Évoluer dans un environnement numérique »',D3+', compétence 3.2 « Développer des documents multimédia »',CRCN],
 tip:'Pour partager un document qui doit s’afficher pareil partout : PDF. Pour qu’un camarade puisse le modifier : le format du logiciel (odt, docx…).',
 c:C(`Tu envoies ton exposé et ton professeur ne peut pas l’ouvrir : c’est un problème de <b>format</b>. Chaque type de fichier a un format, souvent repéré par son extension, et tous les logiciels ne les lisent pas tous. Il faut aussi tenir compte de la <b>taille</b> des fichiers.`,
  [T('Formats ouverts, formats propriétaires',`<p>Un <b>format ouvert</b> a des règles publiques : n’importe quel logiciel peut le lire (odt, ods, png, txt, html…). Un <b>format propriétaire</b> appartient à une entreprise (docx, xlsx en partie, certains formats d’applications). Le <b>PDF</b> est une norme internationale (ISO) qui garde la mise en page à l’identique.</p>`),
   T('Taille et compression',`<p>La taille d’un fichier se mesure en <b>octets</b> : 1 ko = 1 000 octets, 1 Mo = 1 000 ko, 1 Go = 1 000 Mo. Une image ou une vidéo peut être <b>compressée</b> (jpg, mp4) pour être plus légère, parfois avec une perte de qualité. Un dossier entier peut être réuni dans une <b>archive</b> zip.</p>`)],
  [{q:'Ton exposé de 3 pages contient 8 photos de 4 Mo chacune. La messagerie limite les pièces jointes à 10 Mo. Que faire ?',s:['Taille des photos : 8 × 4 = 32 Mo, trop lourd.','Réduire la taille des images (redimensionner ou compresser).','Exporter le document en PDF et vérifier qu’il fait moins de 10 Mo, ou déposer le fichier dans l’espace de l’ENT.']}],
  ['Je choisis le format selon l’usage (modifier ou consulter).','Je vérifie la taille avant d’envoyer.','Je compresse les images si besoin.','Je privilégie les formats ouverts pour la compatibilité.'],
  ['Renommer « exposé.odt » en « exposé.pdf » en croyant convertir le fichier.','Envoyer une vidéo de 2 Go par courriel.','Confondre Mo et Go.'],
  ['Format ouvert : lisible par tous.','PDF : mise en page fixe.','1 Go = 1 000 Mo = 1 000 000 ko.']),
 g:mix([d=>{const k=R(0,2),[u,f]=SIZES[k],[u2,f2]=SIZES[k+1];const n=P([2,3,5,8,12,25,40]);return num(`Combien de ${u} font ${n} ${u2} ?`,n*1000,{unit:u,expl:`1 ${u2} = 1 000 ${u} donc ${n} ${u2} = <b>${nf(n*1000)} ${u}</b>.`,hint:'On multiplie par 1 000.'});},2],
  [d=>{const n=R(3,12),s=R(2,9),lim=P([10,20,25]);const tot=n*s;return ch(`${n} photos de ${s} Mo chacune peuvent-elles être envoyées en une pièce jointe limitée à ${lim} Mo ?`,tot<=lim?'Oui':'Non',[tot<=lim?'Non':'Oui'],{expl:`${n} × ${s} = ${tot} Mo, ${tot<=lim?'ce qui est inférieur ou égal':'ce qui dépasse'} la limite de ${lim} Mo.`,hint:'Calcule la taille totale.'});},2],
  [pairs([['PDF','garder une mise en page identique sur tous les appareils'],['JPG','une photo compressée'],['PNG','une image sans perte de qualité'],['ZIP','une archive qui regroupe plusieurs fichiers'],['MP3','un son compressé'],['TXT','un texte brut sans mise en forme']],{q:'Le format %s sert à…',rq:'Quel format choisir pour %s ?'}),2],
  [bank([
   ['Qu’est-ce qu’un format ouvert ?','un format dont les règles sont publiques',['un format payant','un format qu’on ne peut pas fermer','un fichier sans mot de passe'],'Tout logiciel peut le lire et l’écrire.'],
   ['Renommer « exposé.odt » en « exposé.pdf »…','ne convertit pas le fichier',['le convertit en PDF','le compresse','le protège'],'Il faut utiliser « Exporter en PDF ».'],
   ['Lequel est le plus grand ?','1 Go',['1 Mo','1 ko','100 ko'],'1 Go = 1 000 Mo.'],
   ['Compresser une image sert à…','réduire sa taille en octets',['l’agrandir','changer son auteur','la rendre plus nette'],'Utile pour l’envoyer.'],
   {tf:'Un fichier PDF s’affiche avec la même mise en page sur presque tous les appareils.',v:true,e:'C’est sa principale utilité.'},
   ['Ton camarade doit compléter ton texte. Tu lui envoies…','le fichier au format du traitement de texte (odt)',['un PDF','une capture d’écran','une impression'],'Il faut un format modifiable.',2]]),2])},

{id:'pix5f',name:'Sécuriser ses comptes et ses appareils',icon:'🔒',domain:'Protection et sécurité',
 refs:[D4+', compétence 4.1 « Sécuriser l’environnement numérique »',CRCN],
 tip:'Les quatre réflexes : mots de passe solides et différents, mises à jour faites, double authentification activée, prudence avec les liens et les applications inconnues.',
 c:C(`Ton téléphone, ta tablette, ta console contiennent tes photos, tes messages, tes comptes. Un appareil mal protégé peut être piraté ou infecté par un <b>logiciel malveillant</b>. Quelques réflexes simples réduisent beaucoup les risques.`,
  [T('Protéger ses comptes',`<p>Mots de passe robustes et différents, <b>double authentification</b> (un code reçu sur le téléphone en plus du mot de passe), verrouillage de l’écran (code, schéma), vérification des connexions inhabituelles.</p>`),
   T('Protéger ses appareils',`<p>Faire les <b>mises à jour</b> (elles corrigent des failles de sécurité), installer les applications depuis les magasins officiels, vérifier les <b>autorisations</b> demandées (micro, caméra, localisation, contacts), se méfier des réseaux Wi-Fi publics. Un <b>logiciel malveillant</b> (virus, rançongiciel, logiciel espion) peut voler ou bloquer des données.</p>`)],
  [{q:'Une application de lampe torche demande l’accès à tes contacts, ton micro et ta position. Que faire ?',s:['Une lampe torche n’a besoin que du flash.','Ces autorisations sont suspectes : l’application peut collecter tes données.','Refuser les autorisations ou désinstaller l’application.']}],
  ['J’active le verrouillage de l’écran.','J’installe les mises à jour.','J’active la double authentification sur mes comptes importants.','Je vérifie les autorisations des applications.'],
  ['Repousser toujours les mises à jour.','Installer une application trouvée sur un site inconnu.','Accepter toutes les autorisations sans lire.'],
  ['Mises à jour = corrections de sécurité.','Double authentification.','Autorisations : seulement l’utile.']),
 g:mix([bank([
  ['Pourquoi faire les mises à jour de son téléphone ?','elles corrigent des failles de sécurité',['elles effacent les photos','elles ralentissent volontairement l’appareil','elles changent le mot de passe'],'Les failles connues sont réparées.'],
  ['La double authentification, c’est…','un code supplémentaire en plus du mot de passe',['deux mots de passe identiques','deux comptes pour une personne','un antivirus'],'Même avec ton mot de passe, un pirate ne peut pas entrer.'],
  ['Une application de jeu demande l’accès à tes contacts. Tu…','refuses si ce n’est pas utile au jeu',['acceptes toujours','donnes aussi ta position','lui envoies ton mot de passe'],'N’accorder que les autorisations nécessaires.'],
  ['Où installer des applications de préférence ?','depuis le magasin officiel de l’appareil',['depuis un lien reçu par un inconnu','depuis n’importe quel site','depuis une clé USB trouvée'],'Les applications y sont contrôlées.'],
  ['Un rançongiciel…','bloque des fichiers et demande une rançon',['accélère l’ordinateur','protège des virus','sauvegarde les données'],'Il faut des sauvegardes pour s’en protéger.',2],
  ['Le verrouillage de l’écran sert à…','empêcher quelqu’un d’utiliser ton appareil',['économiser la batterie seulement','prendre des photos','télécharger plus vite'],'Code, schéma ou empreinte.'],
  ['Sur un Wi-Fi public, il vaut mieux éviter…','de se connecter à des comptes sensibles',['de lire un article','de consulter la météo','de regarder un plan'],'Les échanges peuvent être espionnés.',2],
  ['Un logiciel espion…','collecte tes informations à ton insu',['protège tes mots de passe','met à jour l’appareil','supprime les publicités'],'Il espionne messages, positions, frappes.',2],
  ['Une clé USB trouvée dans la cour…','ne doit pas être branchée : elle peut contenir un logiciel malveillant',['peut être utilisée sans risque','doit être formatée sur l’ordinateur du CDI','est un cadeau'],'On la remet à un adulte.',2],
  ['Tu reçois une alerte « connexion inhabituelle à ton compte ». Que fais-tu ?','je change mon mot de passe et je préviens un adulte',['je l’ignore','je supprime l’application de messagerie','je partage l’alerte sur un réseau social'],'Quelqu’un a peut-être ton mot de passe.'],
  {tf:'Un antivirus à jour dispense de toute prudence.',v:false,e:'La prudence reste indispensable.'},
  {tf:'Une application gratuite peut gagner de l’argent en collectant des données.',v:true,e:'« Si c’est gratuit, c’est peut-être toi le produit. »',d:2},
  ['Quelle autorisation est logique pour une application de cartes ?','la localisation',['les contacts','les SMS','le journal d’appels'],'Elle doit savoir où tu es.',3]]),1])},

{id:'pix5g',name:'Résoudre un problème technique simple',icon:'🛠️',domain:'Environnement numérique',
 refs:[D5+', compétence 5.1 « Résoudre des problèmes techniques »',CRCN],
 tip:'Avant de paniquer : observe, lis le message d’erreur, vérifie le plus simple (câble, volume, Wi-Fi), redémarre, puis cherche de l’aide en décrivant précisément le problème.',
 c:C(`Plus de son, l’imprimante ne répond pas, la page web ne charge pas… La plupart des pannes ont des causes simples. Une <b>démarche méthodique</b> permet souvent de les résoudre seul, ou au moins de bien expliquer le problème à quelqu’un.`,
  [T('Une démarche de dépannage',`<p>1. <b>Observer</b> : que se passe-t-il exactement ? Y a-t-il un message d’erreur ? 2. <b>Vérifier l’évident</b> : branchement, alimentation, volume, Wi-Fi activé, mode avion. 3. <b>Tester</b> une hypothèse à la fois. 4. <b>Redémarrer</b> l’application ou l’appareil. 5. <b>Chercher de l’aide</b> : aide en ligne, adulte, en décrivant précisément le problème.</p>`),
   T('Connaître son matériel',`<p><b>Périphériques</b> d’entrée (clavier, souris, micro), de sortie (écran, imprimante, haut-parleurs). Ports et connexions (USB, HDMI, Bluetooth, Wi-Fi). Un <b>pilote</b> permet à l’ordinateur de reconnaître un périphérique.</p>`)],
  [{q:'Le son ne fonctionne plus sur l’ordinateur. Que faire ?',s:['Vérifier le volume (pas en muet) et le casque ou les haut-parleurs branchés.','Vérifier la sortie audio choisie dans les paramètres.','Redémarrer l’application, puis l’ordinateur ; sinon, prévenir l’adulte en décrivant le problème.']}],
  ['J’observe et je lis le message d’erreur.','Je vérifie les causes simples.','Je teste une seule chose à la fois.','Je redémarre, puis je demande de l’aide avec une description précise.'],
  ['Cliquer partout en même temps.','Débrancher l’ordinateur pendant une mise à jour.','Dire seulement « ça marche pas » sans détails.'],
  ['Observer, vérifier l’évident, tester, redémarrer, demander.','Entrée / sortie.','Décrire précisément le problème.']),
 g:mix([sort({'un périphérique d’entrée':['le clavier','la souris','le micro','le scanner','la webcam'],'un périphérique de sortie':['l’écran','l’imprimante','les haut-parleurs','le casque audio','le vidéoprojecteur']},{q:'« %s » est…'}),2],
  [bank([
   ['La page web ne charge pas. Que vérifier d’abord ?','la connexion Internet (Wi-Fi activé, mode avion désactivé)',['racheter un ordinateur','réinstaller le système','changer de clavier'],'On commence par la cause la plus simple.'],
   ['L’imprimante ne répond pas. Première vérification ?','qu’elle est allumée, branchée et qu’il y a du papier',['changer d’ordinateur','supprimer le document','appeler un technicien tout de suite'],'Vérifier l’évident d’abord.'],
   ['Pourquoi tester une seule hypothèse à la fois ?','pour savoir ce qui a résolu le problème',['parce que c’est plus rapide','pour perdre du temps','c’est obligatoire'],'Sinon on ne sait pas quelle action a marché.',2],
   ['Quelle description aide le plus un adulte à dépanner ?','« Depuis ce matin, Word affiche “fichier corrompu” quand j’ouvre mon exposé. »',['« Ça marche pas. »','« L’ordi est nul. »','« J’ai tout cassé. »'],'Précise : quand, quoi, quel message.'],
   ['À quoi sert le port HDMI ?','à relier un écran ou un vidéoprojecteur',['à recharger le téléphone seulement','à se connecter au Wi-Fi','à brancher un micro'],'Il transmet image et son.'],
   ['Le Bluetooth sert à…','connecter des appareils sans fil à courte distance',['naviguer sur Internet','imprimer à distance dans le monde','sauvegarder sur Internet'],'Casque, enceinte, souris…'],
   ['Un pilote (driver) permet…','à l’ordinateur de reconnaître un périphérique',['de piloter un drone','d’accélérer Internet','de supprimer les virus'],'Logiciel qui fait le lien avec le matériel.',2],
   ['Une application est figée. Que faire ?','la fermer puis la relancer',['éteindre en arrachant la prise','attendre une semaine','supprimer tous les fichiers'],'Si elle reste bloquée, forcer sa fermeture.'],
   {tf:'Il faut éviter d’éteindre un ordinateur pendant une mise à jour.',v:true,e:'Cela peut endommager le système.',d:2},
   ['Le micro ne fonctionne pas en visioconférence. Vérifie d’abord…','qu’il n’est pas coupé et que l’application a l’autorisation d’utiliser le micro',['la luminosité de l’écran','la taille de la police','le mot de passe de l’ENT'],'Autorisations et bouton muet.',2],
   {o:['Observer le problème','Vérifier les causes simples','Redémarrer','Demander de l’aide'],q:'Remets dans l’ordre la démarche de dépannage :',e:'Observer → vérifier → redémarrer → aide.',d:2}]),3])},

{id:'pix5h',name:'S’entraîner sur des épreuves Pix',icon:'🏋️',domain:'Pix',
 refs:[CRCN,NS+' : en 5e et 4e, les élèves poursuivent le développement de leurs compétences avec des parcours Pix proposés par les enseignants'],
 tip:'Une épreuve Pix est un petit défi : lis la consigne, cherche (le web est souvent autorisé), et pense à vérifier ta réponse avant de valider.',
 c:C(`Sur Pix, les épreuves ne sont pas que des QCM : il faut parfois <b>chercher sur le web</b>, <b>manipuler un fichier</b>, trouver une information dans une image. Comprendre comment fonctionne la plateforme aide à progresser.`,
  [T('Comment fonctionne Pix',`<p>Les questions sont <b>adaptatives</b> : réussir fait monter le niveau, échouer le fait baisser. On gagne des <b>pix</b> (points) et des <b>niveaux</b> par compétence. Certaines épreuves sont <b>chronométrées</b>. On peut passer une question, mais on ne revient pas en arrière.</p><p>Les enseignants proposent des <b>campagnes</b> (parcours) avec un code. Les <b>tutoriels</b> proposés après une erreur aident à comprendre.</p>`),
   T('Bonnes stratégies',`<p>Lire toute la consigne et les fichiers joints. Utiliser les outils autorisés (moteur de recherche, logiciel). Vérifier le format attendu de la réponse (un nombre, un mot, une date). Ne pas répondre au hasard : les erreurs aident Pix à trouver ton niveau.</p>`)],
  [{q:'Épreuve : « Quelle est la date de création de ce fichier image ? » avec un fichier joint.',s:['Télécharger le fichier.','Ouvrir ses propriétés (clic droit › Propriétés, ou informations de l’image).','Lire la date et la saisir au format demandé.']}],
  ['Je lis toute la consigne.','J’ouvre les fichiers joints.','J’utilise les outils autorisés.','Je vérifie le format de ma réponse.'],
  ['Répondre au hasard.','Ignorer le fichier joint.','Se décourager après une erreur : le niveau s’adapte.'],
  ['Questions adaptatives.','Pix et niveaux par compétence.','Tutoriels après les erreurs.']),
 g:mix([d=>{const lv=R(1,7);return ch(`Sur Pix, tu es au niveau ${lv} dans une compétence. Tu réussis plusieurs épreuves de niveau ${lv+1}. Que va-t-il se passer ?`,`ton niveau peut monter à ${lv+1}`,[`ton niveau baisse à ${lv-1<0?0:lv-1}`,'rien ne change jamais','tu obtiens directement le niveau 8'],{expl:'Les épreuves s’adaptent et le niveau progresse avec les réussites.',hint:'Pix est adaptatif.'});},1],
  [bank([
   ['Que signifie « adaptatif » pour les questions Pix ?','la difficulté change selon tes réponses',['les questions sont toujours les mêmes','la question s’adapte à ta taille d’écran seulement','il n’y a qu’une question'],'Réussir fait monter le niveau.'],
   ['Sur Pix, peut-on parfois utiliser un moteur de recherche ?','oui, beaucoup d’épreuves l’autorisent',['non, jamais','seulement en 3e','seulement le samedi'],'Savoir chercher est une compétence évaluée.'],
   ['Après une erreur sur Pix, que proposent souvent les résultats ?','des tutoriels pour comprendre',['une punition','la bonne réponse de tous les élèves','la fin de la campagne'],'Pour progresser.'],
   ['Une « campagne » Pix, c’est…','un parcours proposé par un enseignant avec un code',['une publicité','un jeu vidéo','une note du brevet'],'On y accède avec un code.'],
   ['Une épreuve demande « la réponse en chiffres ». Tu écris…','12',['douze','environ douze','12 ou 13'],'Respecter le format attendu.'],
   ['Une épreuve Pix fournit un fichier. Que faire ?','l’ouvrir et l’examiner',['l’ignorer','le supprimer','le renommer'],'La réponse s’y trouve souvent.'],
   ['Combien de niveaux maximum Pix définit-il par compétence ?','8',['5','3','16'],'Les niveaux vont de 1 à 8.',2],
   ['Sur Pix, l’unité de score s’appelle…','le pix',['le point Bonus','le joker','la médaille'],'On cumule des pix.',2],
   {tf:'Répondre au hasard permet d’obtenir un niveau plus juste.',v:false,e:'Mieux vaut passer la question ou réfléchir.'},
   {tf:'Sur Pix, une épreuve peut être chronométrée.',v:true,e:'Un compte à rebours s’affiche alors.',d:2},
   ['Où trouver la date de création d’un fichier ?','dans ses propriétés',['dans son nom','dans la corbeille','dans l’historique du navigateur'],'Clic droit › Propriétés (ou Informations).',2],
   ['Que faire si tu ne sais vraiment pas répondre ?','passer la question',['demander la réponse au voisin','fermer Pix','cliquer au hasard'],'Passer est honnête et n’empêche pas de progresser.']]),3])}
]);

MQ.add('pix','4',[
{id:'pix4a',name:'Utiliser un tableur : formules et calculs',icon:'🧮',domain:'Information et données',
 refs:[D1+', compétence 1.3 « Traiter des données »',D3+', compétence 3.3 « Adapter les documents à leur finalité »',CRCN],
 tip:'Une formule commence toujours par = et utilise les ADRESSES des cellules (=B2*C2) plutôt que les nombres : si une valeur change, le résultat se met à jour.',
 c:C(`Calculer le budget d’une sortie, la moyenne d’une série de notes, le total d’une commande : le <b>tableur</b> (LibreOffice Calc, Excel…) fait ces calculs automatiquement, à condition de savoir écrire des <b>formules</b>.`,
  [T('Formules',`<p>Une formule commence par <b>=</b>. Elle utilise les opérations + − * / et les <b>références</b> de cellules : <b>=B2*C2</b> multiplie le contenu de B2 par celui de C2. Les <b>fonctions</b> simplifient : <b>=SOMME(B2:B10)</b> additionne la plage B2 à B10, <b>=MOYENNE(B2:B10)</b>, <b>=MAX(…)</b>, <b>=MIN(…)</b>.</p>`),
   T('Recopier une formule',`<p>En tirant la poignée de recopie vers le bas, <b>=B2*C2</b> devient <b>=B3*C3</b>, puis <b>=B4*C4</b> : les références sont <b>relatives</b>. Pour bloquer une cellule (un taux, un prix unitaire), on utilise une référence <b>absolue</b> : <b>$E$1</b>.</p>`)],
  [{q:'Budget d’une sortie : colonne B = prix unitaire, colonne C = quantité, colonne D = coût. Que mettre en D2, puis le total ?',s:['En D2 : =B2*C2, puis recopier vers le bas.','Total en D7 : =SOMME(D2:D6).','Si un prix change, les coûts et le total se mettent à jour seuls.']}],
  ['Je commence la formule par =.','J’utilise les adresses des cellules.','J’utilise SOMME, MOYENNE, MAX, MIN.','Je recopie et je bloque avec $ si nécessaire.'],
  ['Oublier le = (le tableur affiche le texte).','Taper les nombres dans la formule au lieu des références.','Oublier le $ pour une cellule fixe : la recopie se décale.'],
  ['=, références, fonctions.','B2:B10 = plage de cellules.','Relatif (B2) / absolu ($B$2).']),
 g:mix([d=>{const a=R(2,9),b=R(3,40),c='BCDE'[R(0,3)];const l=R(2,9);return num(`En ${c}${l} il y a ${a} et en ${String.fromCharCode(c.charCodeAt(0)+1)}${l} il y a ${b}. Quel résultat affiche la formule =${c}${l}*${String.fromCharCode(c.charCodeAt(0)+1)}${l} ?`,a*b,{expl:`${a} × ${b} = <b>${a*b}</b>.`,hint:'* signifie « multiplié par ».'});},2],
  [d=>{const n=R(3,6),v=Array.from({length:n},()=>R(5,20));let s=v.reduce((x,y)=>x+y,0);const fn=d>=2?P(['SOMME','MOYENNE','MAX','MIN']):'SOMME';
   if(fn==='MOYENNE'){const r=s%n;v[n-1]+=(n-r)%n;s=v.reduce((x,y)=>x+y,0);}
   const res={SOMME:s,MOYENNE:s/n,MAX:Math.max(...v),MIN:Math.min(...v)}[fn];
   return num(`Les cellules B2 à B${n+1} contiennent : ${v.join(' ; ')}. Que renvoie =${fn}(B2:B${n+1}) ?`,res,{expl:`${fn} de ${v.join(' ; ')} = <b>${nf(res)}</b>.`,hint:{SOMME:'On additionne tout.',MOYENNE:'Somme divisée par le nombre de valeurs.',MAX:'La plus grande valeur.',MIN:'La plus petite valeur.'}[fn]});},3],
  [d=>{const c=P(['B','C','D']),l=R(2,6),k=R(1,4);const c2=String.fromCharCode(c.charCodeAt(0)+1);return ch(`La formule =${c}${l}*${c2}${l} est en E${l}. On la recopie ${k} ligne${k>1?'s':''} plus bas. Que devient-elle ?`,`=${c}${l+k}*${c2}${l+k}`,[`=${c}${l}*${c2}${l}`,`=${c}${l+k}*${c2}${l}`,`=${String.fromCharCode(c.charCodeAt(0)+k)}${l}*${c2}${l}`],{expl:`Les références relatives avancent du même nombre de lignes : <b>=${c}${l+k}*${c2}${l+k}</b>.`,hint:'Recopie vers le bas : le numéro de ligne change.'});},2],
  [bank([
   ['Par quel caractère commence une formule de tableur ?','=',['+','#','?'],'Sans =, le tableur affiche le texte tel quel.'],
   ['Que désigne B2:B10 ?','la plage de cellules de B2 à B10',['les cellules B2 et B10 seulement','B2 divisé par B10','la colonne B entière'],'Les deux-points indiquent une plage.'],
   ['Dans une formule, $E$1 est…','une référence absolue qui ne change pas à la recopie',['une somme en euros','une erreur','un texte'],'Le $ bloque la colonne et la ligne.',2],
   ['Pourquoi écrire =B2*C2 plutôt que =4*12 ?','le résultat se met à jour si les valeurs changent',['c’est plus court','le tableur refuse les nombres','c’est plus joli'],'Les références rendent le calcul dynamique.'],
   {tf:'=MOYENNE(B2:B5) divise la somme de B2 à B5 par 4.',v:true,e:'Il y a 4 cellules : B2, B3, B4, B5.',d:2},
   ['Le tableur affiche « #DIV/0! ». Cela signifie…','une division par zéro',['un virus','un fichier corrompu','un nombre trop grand'],'Vérifier le diviseur.',3]]),2])},

{id:'pix4b',name:'Recherche avancée et vérification des sources',icon:'🔬',domain:'Information et données',
 refs:[D1+', compétence 1.1 « Mener une recherche et une veille d’information »',CRCN],
 tip:'Les opérateurs de recherche font gagner du temps : "expression exacte", -motexclu, site:gouv.fr, filetype:pdf.',
 c:C(`Une recherche simple donne des millions de résultats. Avec les <b>opérateurs de recherche</b> et les <b>filtres</b> du moteur, on obtient des résultats plus précis. On remonte ensuite à la <b>source primaire</b> d’une information.`,
  [T('Opérateurs et filtres',`<p><b>"guillemets"</b> : expression exacte. <b>-mot</b> : exclure un mot (« jaguar -voiture »). <b>site:</b> : chercher dans un site ou un domaine (« site:education.gouv.fr brevet »). <b>filetype:</b> : type de fichier (« filetype:pdf »). Les filtres du moteur limitent par <b>date</b>, par type (images, actualités), par langue.</p>`),
   T('Source primaire et citation',`<p>La <b>source primaire</b> est l’origine de l’information (étude scientifique, texte de loi, données officielles) ; un article qui la commente est une source secondaire. On remonte à la source pour vérifier les chiffres. Pour citer : auteur, titre, site, date, adresse (URL), date de consultation.</p>`)],
  [{q:'Trouver le calendrier officiel du brevet sous forme de PDF.',s:['Requête : brevet calendrier site:education.gouv.fr filetype:pdf','Vérifier que le document est bien de l’année en cours.','Noter la source : ministère de l’Éducation nationale, titre, date.']}],
  ['Je choisis les mots-clés.','J’ajoute les opérateurs utiles (guillemets, -, site:, filetype:).','Je filtre par date si l’actualité compte.','Je remonte à la source primaire et je cite.'],
  ['Se contenter d’un article qui « dit qu’une étude dit ».','Oublier la date de la source.','Citer seulement « Internet » comme source.'],
  ['"expression", -mot, site:, filetype:.','Source primaire ≠ source secondaire.','Citer auteur, titre, site, date, URL.']),
 g:mix([pairs([['"cycle de l’eau"','chercher l’expression exacte'],['jaguar -voiture','exclure les résultats contenant « voiture »'],['site:education.gouv.fr','chercher seulement dans le site du ministère'],['filetype:pdf','chercher seulement des fichiers PDF'],['site:fr','chercher dans les sites du domaine français « fr »']],{q:'Dans une recherche, « %s » permet de…',rq:'Quelle écriture permet de %s ?'}),3],
  [bank([
   ['Tu cherches l’animal jaguar mais tu obtiens des voitures. Quelle requête ?','jaguar -voiture',['jaguar voiture','"jaguar voiture"','jaguar site:voiture'],'Le signe moins exclut un mot.'],
   ['Qu’est-ce qu’une source primaire ?','l’origine de l’information (étude, texte de loi, données)',['le premier résultat du moteur','un article qui résume une étude','un commentaire de lecteur'],'On remonte à elle pour vérifier.'],
   ['Pour une actualité, quel filtre est utile ?','le filtre par date',['le filtre par couleur','le filtre par taille d’image','aucun'],'On veut les informations récentes.'],
   ['Que faut-il noter pour citer une page web ?','auteur, titre, site, date et adresse (URL)',['seulement « Internet »','le nombre de mots','la couleur du site'],'La citation permet de retrouver la source.'],
   ['Un article dit « selon une étude… » sans lien ni nom. Tu…','cherches l’étude originale avant de croire le chiffre',['recopies le chiffre','partages l’article','le cites comme source primaire'],'Sans source primaire, prudence.',2],
   ['L’adresse d’une page web s’appelle…','une URL',['un octet','un pixel','un pilote'],'Exemple : https://www.education.gouv.fr',2],
   {tf:'Les résultats d’un moteur de recherche peuvent différer d’une personne à l’autre.',v:true,e:'Ils dépendent de la langue, de la position, de l’historique…',d:2},
   ['« Date de consultation » dans une citation web signifie…','le jour où tu as lu la page',['la date de création du site','la date de naissance de l’auteur','la date d’impression'],'La page a pu changer depuis.',3]]),2])},

{id:'pix4c',name:'Travailler en équipe en ligne',icon:'🌐',domain:'Communication',
 refs:[D2+', compétences 2.3 « Collaborer » et 2.4 « S’insérer dans le monde numérique »',CRCN],
 tip:'Un projet en ligne réussi : un espace partagé organisé, des rôles clairs, des échanges respectueux et une trace des décisions.',
 c:C(`En 4e, les projets s’allongent : journal du collège, projet EPI, mini-entreprise. Il faut organiser un <b>espace de travail partagé</b>, répartir les <b>rôles</b>, suivre l’avancement et communiquer de manière respectueuse : c’est la <b>nétiquette</b>.`,
  [T('Organiser un projet partagé',`<p>Un <b>dossier partagé</b> avec une arborescence claire, un <b>tableau de suivi</b> (tâche, responsable, échéance, état : à faire / en cours / terminé), des droits adaptés. Un compte rendu bref après chaque réunion garde la trace des décisions.</p>`),
   T('Nétiquette et identité',`<p>La <b>nétiquette</b> regroupe les règles de politesse en ligne : saluer, rester courtois, ne pas monopoliser la parole, couper son micro quand on ne parle pas, ne pas diffuser les échanges sans accord. On adapte son langage au destinataire (camarade, professeur, partenaire extérieur).</p>`)],
  [{q:'Organiser le journal du collège (6 rédacteurs).',s:['Un dossier partagé « Journal » avec sous-dossiers Articles, Photos, Maquette.','Un tableau de suivi : article, rédacteur, échéance, état.','Une visioconférence par semaine ; un compte rendu court déposé dans le dossier.']}],
  ['J’organise l’espace partagé.','Je répartis les rôles et les échéances.','Je suis l’avancement dans un tableau.','Je respecte la nétiquette.'],
  ['Tout mettre en vrac dans un seul dossier.','Ne pas noter qui fait quoi.','Parler en même temps en visioconférence.'],
  ['Dossier partagé organisé.','Tableau de suivi : tâche, responsable, échéance, état.','Nétiquette.']),
 g:mix([sort({'À faire':['l’article n’a pas encore été commencé','la photo n’a pas encore été prise'],'En cours':['l’article est à moitié rédigé','la maquette est en préparation'],'Terminé':['l’article est relu et validé','la photo est déposée et légendée']},{q:'Dans le tableau de suivi, quel état pour : « %s » ?'}),1],
  [bank([
   ['La nétiquette, c’est…','l’ensemble des règles de politesse sur Internet',['un logiciel de messagerie','une étiquette de fichier','un réseau social'],'Net + étiquette.'],
   ['En visioconférence, quand tu ne parles pas, tu…','coupes ton micro',['montes le son','parles en même temps','quittes et reviens sans cesse'],'Cela évite les bruits parasites.'],
   ['Un tableau de suivi de projet indique…','la tâche, le responsable, l’échéance et l’état',['seulement le nom du projet','les mots de passe de chacun','les notes des élèves'],'On voit qui fait quoi et pour quand.'],
   ['Pourquoi écrire un compte rendu après une réunion ?','garder une trace des décisions',['remplir l’espace de stockage','faire plaisir au professeur seulement','ce n’est jamais utile'],'Tout le monde peut s’y référer.'],
   ['Tu écris à un partenaire extérieur (une association). Ton message doit être…','poli et soigné, avec une présentation',['écrit en langage SMS','sans objet','en majuscules'],'On adapte son registre.'],
   ['Un membre du groupe ne répond plus. Que faire ?','lui écrire poliment puis en parler au professeur',['l’insulter sur le forum','supprimer sa partie','publier son nom sur un réseau social'],'Rester respectueux.',2],
   ['Une arborescence claire dans un dossier partagé permet…','à chacun de retrouver facilement les fichiers',['d’alourdir les fichiers','d’empêcher les autres de travailler','de supprimer l’historique'],'Organisation commune.'],
   {tf:'On peut diffuser la capture d’écran d’une conversation de groupe sans demander l’accord des participants.',v:false,e:'Il faut respecter la vie privée des autres.'},
   {tf:'Définir des rôles (rédacteur, photographe, relecteur) aide un projet en ligne.',v:true,e:'Chacun sait ce qu’il doit faire.'},
   ['Un « relecteur » dans un projet…','vérifie et corrige les textes des autres',['écrit tous les articles','supprime les fichiers inutiles sans prévenir','gère les mots de passe'],'Il améliore la qualité finale.',2],
   ['Pour décider d’une date de réunion à plusieurs, on peut utiliser…','un sondage de dates en ligne',['un tableur de notes','une carte mentale','un antivirus'],'Chacun indique ses disponibilités.',2],
   ['Une échéance est…','une date limite',['un type de fichier','un mot de passe','une adresse web'],'La date à laquelle la tâche doit être terminée.']]),3])},

{id:'pix4d',name:'Créer un contenu multimédia',icon:'🎬',domain:'Création de contenu',
 refs:[D3+', compétence 3.2 « Développer des documents multimédia »',D2+', compétence 2.2 « Partager et publier »',CRCN],
 tip:'Un bon diaporama : une idée par diapositive, peu de texte, des images libres de droits citées, et une dernière diapositive pour les sources.',
 c:C(`Diaporama pour un exposé, podcast pour la radio du collège, courte vidéo : créer un <b>contenu multimédia</b> associe texte, image, son et vidéo. Il faut savoir les assembler, les rendre lisibles et respecter les <b>droits</b>.`,
  [T('Diaporama et image',`<p>Un <b>diaporama</b> (LibreOffice Impress, PowerPoint) : une idée par diapositive, un titre, des mots-clés plutôt que des phrases longues, une police lisible, un bon contraste. Une image a une <b>résolution</b> (nombre de pixels) : trop petite, elle est floue quand on l’agrandit. On peut la <b>recadrer</b> ou la <b>redimensionner</b>.</p>`),
   T('Son, vidéo et droits',`<p>Un <b>podcast</b> s’enregistre avec un micro et se monte avec un logiciel (Audacity…). Une vidéo se <b>monte</b> : couper, assembler, ajouter titres et musique. On utilise des médias <b>libres de droits</b> ou sous licence <b>Creative Commons</b> en respectant leurs conditions (par exemple <b>BY</b> : citer l’auteur), et on demande l’accord des personnes filmées.</p>`)],
  [{q:'Préparer un diaporama de 5 minutes sur les volcans.',s:['Plan : 6 diapositives (titre, formation, types, risques, exemple, sources).','Une idée par diapositive, des mots-clés, une image sous licence libre par diapositive.','Dernière diapositive : sources et crédits des images (auteur, licence).']}],
  ['Je fais un plan avant de créer.','Une idée et peu de texte par diapositive.','J’utilise des médias libres de droits et je les crédite.','Je vérifie la lisibilité (taille, contraste).'],
  ['Recopier des paragraphes entiers sur les diapositives.','Mettre une musique connue sans droit d’utilisation.','Étirer une petite image : elle devient floue et déformée.'],
  ['Une idée par diapositive.','Pixels, résolution, recadrage.','Licences Creative Commons : respecter les conditions.']),
 g:mix([pairs([['BY','citer l’auteur'],['NC','pas d’utilisation commerciale'],['ND','pas de modification de l’œuvre'],['SA','partager l’œuvre modifiée sous la même licence']],{q:'Dans une licence Creative Commons, la mention « %s » signifie…',rq:'Quelle mention Creative Commons signifie : %s ?'}),2],
  [d=>{const w=P([640,800,1024,1280,1920]),h=w===1920?1080:w*3/4;return num(`Une image mesure ${nf(w)} pixels de large et ${nf(h)} pixels de haut. Combien de pixels contient-elle ?`,w*h,{expl:`${nf(w)} × ${nf(h)} = <b>${nf(w*h)}</b> pixels.`,hint:'Largeur × hauteur.'});},1],
  [bank([
   ['Combien d’idées principales par diapositive ?','une',['cinq','autant que possible','aucune'],'Pour rester lisible.'],
   ['Un pixel est…','un petit point qui compose une image numérique',['un type de fichier son','une police de caractères','un réseau social'],'Une image = une grille de pixels.'],
   ['Que se passe-t-il si on agrandit beaucoup une image de petite résolution ?','elle devient floue ou pixelisée',['elle devient plus nette','elle change de couleur','elle se transforme en vidéo'],'Il n’y a pas assez de pixels.'],
   ['Recadrer une image, c’est…','en garder seulement une partie',['changer sa couleur','la rendre plus lourde','la traduire'],'On coupe les bords inutiles.'],
   ['Un podcast est…','un contenu audio diffusé en ligne',['une image animée','un tableur','un virus'],'Une émission à écouter.'],
   ['Peut-on mettre une chanson à succès en fond de sa vidéo publiée sur Internet ?','pas sans autorisation, car elle est protégée par le droit d’auteur',['oui, toujours','oui, si la vidéo est courte','oui, si on cite le titre'],'Il faut une musique libre ou une autorisation.'],
   ['Monter une vidéo, c’est…','couper, assembler et compléter des séquences',['la regarder','la télécharger','l’imprimer'],'Avec un logiciel de montage.'],
   ['Où indiquer les crédits des images d’un diaporama ?','sur la diapositive concernée ou sur une diapositive finale de sources',['nulle part','dans le nom du fichier','dans les commentaires cachés'],'Respect des auteurs.'],
   {tf:'Un fort contraste entre le texte et le fond rend la diapositive plus lisible.',v:true,e:'Texte foncé sur fond clair, ou l’inverse.',d:2},
   ['Audacity est un logiciel…','de montage audio',['de tableur','de messagerie','de programmation'],'Il permet d’enregistrer et monter des sons.',2]]),3])},

{id:'pix4e',name:'Programmer : algorithmes et code',icon:'💻',domain:'Création de contenu',
 refs:[D3+', compétence 3.4 « Programmer »',CRCN],
 tip:'Avant de coder, décris ton algorithme en français : « répéter 4 fois : avancer de 100, tourner de 90° ». Ensuite, traduis-le en blocs.',
 c:C(`Un <b>algorithme</b> est une suite d’instructions pour résoudre un problème ; un <b>programme</b> est sa traduction dans un langage compris par la machine (Scratch, Python…). Programmer, c’est aussi tester et corriger (<b>déboguer</b>).`,
  [T('Structures de base',`<p><b>Séquence</b> : instructions les unes après les autres. <b>Boucle</b> : répéter (« répéter 10 fois », « répéter jusqu’à »). <b>Condition</b> : « si … alors … sinon ». <b>Variable</b> : une case mémoire nommée qui contient une valeur (score, vies). <b>Événement</b> : déclencheur (« quand le drapeau vert est cliqué »).</p>`),
   T('Tester et déboguer',`<p>Un <b>bogue</b> (bug) est une erreur dans un programme. On teste avec plusieurs valeurs, on exécute pas à pas, on affiche la valeur des variables. On corrige une erreur à la fois.</p>`)],
  [{q:'Faire tracer un carré de côté 100 par le lutin.',s:['Algorithme : répéter 4 fois : avancer de 100 ; tourner de 90°.','Traduction en blocs Scratch : « répéter 4 fois » contenant « avancer de 100 » et « tourner de 90 degrés ».','Test : le lutin revient à son point de départ.']}],
  ['Je décris l’algorithme en français.','Je repère séquence, boucle, condition, variable.','Je traduis en blocs ou en code.','Je teste et je corrige.'],
  ['Copier 4 fois les mêmes blocs au lieu d’une boucle.','Oublier d’initialiser une variable (score à 0 au départ).','Corriger plusieurs choses à la fois sans tester.'],
  ['Séquence, boucle, condition, variable, événement.','Algorithme ≠ programme.','Tester, déboguer.']),
 g:mix([d=>{const n=P([3,4,5,6,8,9,10,12]);return num(`Pour tracer un polygone régulier à ${n} côtés, le lutin répète ${n} fois : avancer, puis tourner de combien de degrés ?`,360/n,{unit:'°',expl:`Le lutin fait un tour complet (360°) en ${n} virages : 360 ÷ ${n} = <b>${nf(360/n)}°</b>.`,hint:'Un tour complet = 360°.'});},2],
  [d=>{const a=R(0,5),k=R(2,6),s=R(2,5);return num(`Une variable score vaut ${a}. On répète ${k} fois : « ajouter ${s} à score ». Que vaut score à la fin ?`,a+k*s,{expl:`${a} + ${k} × ${s} = <b>${a+k*s}</b>.`,hint:'Chaque tour ajoute la même quantité.'});},2],
  [d=>{const x=R(1,20),t=R(5,15);return ch(`Programme : « si x > ${t} alors dire "Grand" sinon dire "Petit" ». Avec x = ${x}, que dit le lutin ?`,x>t?'Grand':'Petit',[x>t?'Petit':'Grand','Rien','Grand puis Petit'],{expl:`${x} ${x>t?'>':'≤'} ${t}, donc la condition est ${x>t?'vraie':'fausse'} : « ${x>t?'Grand':'Petit'} ».`,hint:'Compare x au seuil.'});},2],
  [bank([
   ['Quelle structure permet de répéter des instructions ?','une boucle',['une condition','une variable','un commentaire'],'Exemple : « répéter 10 fois ».'],
   ['Une variable est…','une case mémoire nommée qui contient une valeur',['une erreur de programme','un type d’image','un lutin'],'Exemple : score, vies.'],
   ['« Si … alors … sinon » est…','une condition',['une boucle','une variable','un événement'],'Le programme choisit selon un test.'],
   ['Un bogue est…','une erreur dans un programme',['un insecte qui casse l’ordinateur','un logiciel de dessin','une boucle infinie voulue'],'On le corrige en déboguant.'],
   ['« Quand le drapeau vert est cliqué » est…','un événement qui démarre le programme',['une boucle','une variable','une condition'],'Un déclencheur.'],
   ['Pourquoi mettre le score à 0 au début du jeu ?','pour initialiser la variable',['pour effacer le lutin','pour arrêter le jeu','ce n’est pas utile'],'Sinon il garde la valeur de la partie précédente.',2],
   {o:['quand le drapeau vert est cliqué','mettre score à 0','répéter 10 fois','ajouter 1 à score','dire score'],q:'Remets dans l’ordre ce programme qui compte jusqu’à 10 :',e:'Événement → initialisation → boucle → instruction répétée → affichage.',d:3},
   {tf:'Un algorithme peut s’écrire en français avant d’être programmé.',v:true,e:'On le traduit ensuite dans un langage.'}]),2])},

{id:'pix4f',name:'Cybersécurité : repérer l’hameçonnage',icon:'🎣',domain:'Protection et sécurité',
 refs:[D4+', compétence 4.1 « Sécuriser l’environnement numérique »',CRCN],
 tip:'Urgence + menace ou cadeau + lien + demande d’identifiants = hameçonnage. Ne clique pas : va toi-même sur le site officiel.',
 c:C(`« Votre compte sera supprimé dans 24 h, cliquez ici ! » ; « Vous avez gagné un téléphone ! ». L’<b>hameçonnage</b> (phishing) est une arnaque qui imite un organisme connu pour voler des mots de passe, des données ou de l’argent.`,
  [T('Reconnaître un message piégé',`<p>Indices : <b>urgence</b> ou menace, cadeau trop beau, fautes, adresse de l’expéditeur bizarre (service-client@laposte-securite.info), <b>lien</b> dont l’adresse réelle ne correspond pas au site officiel, demande de mot de passe ou de code. Les vrais services ne demandent jamais ton mot de passe par message.</p>`),
   T('Réagir',`<p>Ne pas cliquer, ne pas répondre, ne pas ouvrir la pièce jointe. Vérifier en allant soi-même sur le site officiel. Signaler (bouton « signaler », 33700 pour les SMS indésirables, plateforme cybermalveillance.gouv.fr). Si on a donné son mot de passe : le changer immédiatement et prévenir un adulte.</p>`)],
  [{q:'SMS : « Colis en attente. Payez 1,99 € de frais : https://colis-livraison-fr.top ». Analyse.',s:['Tu n’attends pas de colis ; l’adresse n’est pas celle d’un transporteur officiel.','Demande de paiement pour un petit montant : technique classique pour voler la carte bancaire.','Ne pas cliquer ; transférer au 33700 ; supprimer.']}],
  ['Je repère l’urgence, le cadeau ou la menace.','Je vérifie l’expéditeur et l’adresse réelle du lien.','Je ne clique pas et je vais moi-même sur le site officiel.','Je signale et je préviens un adulte si besoin.'],
  ['Cliquer « pour voir ».','Donner un code reçu par SMS à quelqu’un qui le demande.','Croire un message parce qu’il a le logo d’une marque connue.'],
  ['Urgence, cadeau, lien, identifiants : alerte.','Jamais de mot de passe par message.','33700, cybermalveillance.gouv.fr.']),
 g:mix([d=>{const L=[['https://www.impots.gouv.fr','officielle'],['https://www.ameli.fr','officielle'],['https://www.laposte.fr','officielle'],['https://impots-gouv.remboursement-fr.com','piégée'],['http://ameli-securite.info/connexion','piégée'],['https://laposte.fr.suivi-colis.top','piégée'],['https://www.education.gouv.fr','officielle'],['https://education-gouv.bourse-aide.net','piégée']];const [u,k]=P(L);return ch(`L’adresse « <b>${u}</b> » semble-t-elle officielle ou piégée ?`,k,[k==='officielle'?'piégée':'officielle'],{expl:k==='officielle'?'Le nom de domaine est bien celui de l’organisme.':'Le vrai nom de domaine est ce qui se trouve juste avant la première barre « / » : ici ce n’est pas celui de l’organisme.',hint:'Regarde la fin du nom de domaine, juste avant le premier « / ».'});},3],
  [bank([
   ['L’hameçonnage (phishing) cherche à…','voler des identifiants, des données ou de l’argent',['réparer ton ordinateur','te protéger des virus','accélérer Internet'],'Le message imite un organisme connu.'],
   ['Un message te demande ton mot de passe « pour vérifier ton compte ». Tu…','ne réponds pas : aucun service sérieux ne le demande',['le donnes rapidement','le donnes sans les majuscules','réponds avec un autre mot de passe'],'C’est une tentative d’hameçonnage.'],
   ['Quel numéro reçoit les SMS indésirables à signaler ?','33700',['3018','112','17'],'On y transfère le SMS suspect.'],
   ['Quel site public aide les victimes d’attaques informatiques ?','cybermalveillance.gouv.fr',['cybermalveillance-aide.com','securite-gratuite.net','pix.fr'],'C’est le dispositif national d’assistance.',2],
   ['Indice d’hameçonnage :','« Votre compte sera supprimé dans 24 h, cliquez ici »',['un message de ton professeur sur l’ENT que tu attendais','une facture que tu as demandée','une réponse à ton propre message'],'L’urgence pousse à agir sans réfléchir.'],
   ['Tu as saisi ton mot de passe sur un faux site. Que faire ?','changer immédiatement le mot de passe et prévenir un adulte',['attendre','supprimer le message seulement','créer un deuxième compte'],'Il faut agir vite.'],
   ['Comment voir la vraie adresse d’un lien sur ordinateur, sans cliquer ?','survoler le lien avec la souris',['cliquer deux fois','l’imprimer','le copier dans un document'],'L’adresse réelle s’affiche en bas de la fenêtre.',2],
   {tf:'Un message qui affiche le logo d’une banque vient forcément de cette banque.',v:false,e:'Un logo se copie très facilement.'},
   ['Le « cadeau » d’un téléphone gratuit contre ton adresse et ton numéro de carte est…','une arnaque probable',['une offre normale','un concours officiel','une mise à jour'],'Trop beau pour être vrai.'],
   ['Quelqu’un te demande le code reçu par SMS « par erreur ». Tu…','refuses : ce code protège ton compte',['le lui envoies','le publies','le donnes s’il est poli'],'C’est souvent pour pirater ton compte.',2]]),2])},

{id:'pix4g',name:'Maîtriser son empreinte numérique',icon:'👣',domain:'Protection et sécurité',
 refs:[D4+', compétence 4.2 « Protéger les données personnelles et la vie privée »',D2+', compétence 2.4 « S’insérer dans le monde numérique »',CRCN],
 tip:'Avant de publier, demande-toi : « Est-ce que ça me gênerait que mon futur employeur, mes parents ou toute ma classe le voient dans 10 ans ? »',
 c:C(`Chaque publication, chaque « j’aime », chaque recherche laisse une trace : c’est l’<b>empreinte numérique</b>. Elle forme ton <b>identité numérique</b>, c’est-à-dire l’image que les autres peuvent avoir de toi en ligne. Elle est difficile à effacer.`,
  [T('Traces volontaires et involontaires',`<p>Traces <b>volontaires</b> : publications, photos, commentaires, profil. Traces <b>involontaires</b> : historique de navigation, <b>cookies</b>, localisation, métadonnées des photos, ce que les autres publient sur toi. Une publication peut être <b>copiée</b> (capture d’écran) et republiée même après suppression.</p>`),
   T('Garder le contrôle',`<p>Régler la <b>confidentialité</b> des comptes, refuser les cookies non nécessaires, désactiver la localisation inutile, rechercher son propre nom pour voir ce qui apparaît. Le <b>droit à l’oubli</b> (RGPD) permet de demander l’effacement de certaines données, notamment publiées quand on était mineur ; la CNIL aide à faire valoir ces droits.</p>`)],
  [{q:'Malik veut publier une photo de lui devant chez lui, avec sa rue visible, en mode public. Conseils ?',s:['La photo révèle son adresse : information sensible.','Elle peut être copiée et rester en ligne longtemps.','Mieux : recadrer pour cacher la rue, publier en mode privé pour ses amis, ou ne pas publier.']}],
  ['Je réfléchis avant de publier.','Je règle la confidentialité de mes comptes.','Je limite cookies et localisation.','Je demande l’effacement si besoin (droit à l’oubli).'],
  ['Croire qu’une publication supprimée a disparu partout.','Publier sa localisation en direct.','Accepter tous les cookies sans lire.'],
  ['Empreinte = traces volontaires et involontaires.','Identité numérique.','Droit à l’oubli, CNIL.']),
 g:mix([sort({'une trace volontaire':['une photo que je publie','un commentaire que j’écris','ma photo de profil','une vidéo que je poste'],'une trace involontaire':['mon historique de navigation','un cookie déposé par un site','la position GPS enregistrée dans une photo','une photo de moi publiée par un ami']},{q:'« %s » est…'}),2],
  [bank([
   ['L’empreinte numérique, c’est…','l’ensemble des traces laissées en ligne',['une empreinte digitale scannée','un mot de passe','un antivirus'],'Volontaires ou non.'],
   ['Un cookie est…','un petit fichier déposé par un site qui enregistre des informations sur ta navigation',['un biscuit offert par le site','un virus dangereux','un mot de passe'],'Il peut servir à la publicité ciblée.'],
   ['Une publication supprimée…','peut avoir été copiée et rester en ligne',['disparaît toujours partout','n’a jamais été vue','est effacée des captures d’écran'],'D’où l’importance de réfléchir avant.'],
   ['Le droit à l’oubli permet…','de demander l’effacement de certaines données personnelles',['d’oublier son mot de passe','de supprimer Internet','de ne plus aller en cours'],'Prévu par le RGPD.',2],
   ['Quel organisme français protège les données personnelles ?','la CNIL',['la SNCF','l’INSEE','le CNED'],'Commission nationale de l’informatique et des libertés.',2],
   ['Rechercher son propre nom en ligne permet…','de voir ce que les autres peuvent trouver sur soi',['de devenir célèbre','d’effacer ses traces','d’augmenter ses abonnés'],'C’est un bon réflexe de vérification.'],
   ['Les métadonnées d’une photo peuvent contenir…','la date et le lieu de prise de vue',['le mot de passe du téléphone','la voix du photographe','rien du tout'],'Données cachées dans le fichier.',3],
   {tf:'Ce que tes amis publient sur toi fait aussi partie de ton identité numérique.',v:true,e:'Ce sont des traces que tu ne contrôles pas.'},
   {tf:'Un compte réglé en « privé » empêche toute copie de tes publications.',v:false,e:'Un abonné peut faire une capture d’écran.',d:2},
   ['L’identité numérique, c’est…','l’image de toi que donnent les informations en ligne',['ta carte d’identité scannée','ton numéro de téléphone','ton adresse électronique seulement'],'Elle se construit avec tes traces et celles des autres.']]),2])},

{id:'pix4h',name:'Intelligence artificielle : comprendre et bien l’utiliser',icon:'🤖',domain:'Pix',
 refs:[NS+' : en 4e, deux parcours Pix obligatoires consacrés à l’intelligence artificielle (environ 30 à 45 minutes chacun), mis en œuvre progressivement de 2025 à 2027, sans attestation',CRCN],
 tip:'Une IA générative PRÉDIT des mots ou des images probables : elle peut se tromper avec assurance. Vérifie toujours ce qu’elle affirme, et ne lui confie pas de données personnelles.',
 c:C(`Assistants conversationnels, traduction automatique, filtres photo, recommandations de vidéos : l’<b>intelligence artificielle</b> (IA) est partout. En 4e, deux parcours Pix sont consacrés à l’IA : comprendre comment elle fonctionne, ses limites et comment l’utiliser de manière responsable.`,
  [T('Comment fonctionne une IA',`<p>Une IA d’<b>apprentissage automatique</b> est entraînée sur une grande quantité de <b>données</b> pour repérer des régularités. Une <b>IA générative</b> (texte, image, son) produit un contenu nouveau en prédisant, étape par étape, ce qui est le plus probable. Elle ne « comprend » pas comme un humain et ne vérifie pas la vérité.</p>`),
   T('Limites et usage responsable',`<p>Une IA peut <b>se tromper</b> (inventer des faits ou des sources : « hallucinations »), reproduire des <b>biais</b> présents dans ses données, produire des <b>hypertrucages</b> (deepfakes). On vérifie ses réponses avec des sources fiables, on ne lui donne pas de données personnelles, on indique quand on l’a utilisée et on respecte les règles fixées par les professeurs.</p>`)],
  [{q:'Un assistant IA te donne une date historique et cite un livre que tu ne trouves nulle part. Que faire ?',s:['L’IA a pu inventer la source (hallucination).','Vérifier la date dans une encyclopédie ou un manuel.','Ne citer que des sources que tu as réellement consultées.']}],
  ['Je formule une demande précise.','Je vérifie les faits avec des sources fiables.','Je ne donne pas de données personnelles.','Je signale mon usage de l’IA et respecte les consignes.'],
  ['Croire une réponse parce qu’elle est bien écrite.','Rendre un devoir écrit par une IA comme s’il était de soi.','Partager une vidéo truquée sans vérifier.'],
  ['IA : entraînée sur des données, elle prédit.','Hallucinations, biais, hypertrucages.','Vérifier, protéger ses données, être transparent.']),
 g:mix([sort({'Utilise de l’IA':['la traduction automatique d’un texte','les recommandations de vidéos','la reconnaissance faciale pour déverrouiller un téléphone','un assistant conversationnel','un filtre photo qui modifie un visage'],'N’utilise pas d’IA':['une calculatrice de poche simple','un interrupteur de lampe','une règle graduée','un livre papier']},{q:'« %s » : avec ou sans intelligence artificielle ?'}),2],
  [bank([
   ['Une IA générative…','produit un contenu nouveau en prédisant ce qui est probable',['vérifie toujours la vérité','pense exactement comme un humain','ne fait jamais d’erreur'],'Elle génère texte, image ou son.'],
   ['Une « hallucination » d’IA, c’est…','une information inventée présentée comme vraie',['un rêve de l’ordinateur','un virus','une panne d’écran'],'Il faut vérifier les réponses.'],
   ['Un hypertrucage (deepfake) est…','une vidéo ou un son truqué par IA pour imiter une personne',['un filtre de couleur','un jeu vidéo','un antivirus'],'Il peut servir à manipuler.'],
   ['Une IA est entraînée à partir…','de grandes quantités de données',['de rien','d’un seul exemple','des rêves de ses créateurs'],'Elle apprend des régularités.'],
   ['Un biais d’IA vient souvent…','de données d’entraînement déséquilibrées',['de l’écran','du clavier','de la couleur du logiciel'],'L’IA reproduit ce qu’elle a vu.',2],
   ['Que ne faut-il pas donner à un assistant IA ?','des données personnelles (adresse, mots de passe, photos d’autres personnes)',['une question de mathématiques','une demande de reformulation','un sujet d’exposé'],'Elles peuvent être conservées et réutilisées.'],
   ['Tu utilises une IA pour t’aider dans un devoir. Tu dois…','respecter les consignes du professeur et indiquer ton usage',['cacher que tu l’as utilisée','recopier sans lire','donner ton mot de passe ENT'],'Honnêteté intellectuelle.'],
   ['Combien de parcours Pix sur l’IA sont prévus en 4e ?','2',['1','4','aucun'],'Deux parcours d’environ 30 à 45 minutes chacun.',2],
   ['Les parcours IA de 4e donnent-ils lieu à une attestation ?','non',['oui, une attestation notée','oui, un diplôme','oui, des points au brevet'],'Ils sont obligatoires mais sans attestation.',3],
   {tf:'Une réponse d’IA très bien rédigée est forcément exacte.',v:false,e:'Le style ne garantit pas la vérité.'},
   {tf:'Une IA peut reproduire des stéréotypes présents dans ses données.',v:true,e:'C’est un biais.',d:2},
   ['Pour obtenir une réponse utile d’un assistant IA, la demande doit être…','précise, avec le contexte et le format attendu',['la plus courte possible, un seul mot','écrite en majuscules','toujours en anglais'],'Une consigne claire donne un meilleur résultat.',2]]),3])}
]);

MQ.add('pix','3',[
{id:'pix3a',name:'Traiter et représenter des données',icon:'📈',domain:'Information et données',
 refs:[D1+', compétences 1.2 « Gérer des données » et 1.3 « Traiter des données »',CRCN],
 tip:'Pour compter selon un critère, pense aux fonctions conditionnelles : =NB.SI(B2:B30;"5e A") compte les cellules égales à « 5e A ».',
 c:C(`Résultats d’une enquête sur les trajets domicile-collège, données ouvertes de la météo, statistiques d’un club : en 3e, on sait importer des données, les <b>nettoyer</b>, les <b>calculer</b> et les <b>représenter</b> pour répondre à une question.`,
  [T('Fonctions utiles',`<p><b>=NB(plage)</b> compte les nombres ; <b>=NB.SI(plage;critère)</b> compte les cellules qui respectent un critère ; <b>=SOMME.SI(plage;critère;plage_somme)</b> additionne selon un critère ; <b>=SI(test;valeur_si_vrai;valeur_si_faux)</b> choisit un résultat. Le <b>tableau croisé dynamique</b> résume un grand tableau (totaux par catégorie).</p>`),
   T('Données ouvertes et format CSV',`<p>Les <b>données ouvertes</b> (open data, data.gouv.fr) sont publiées librement par des organismes. Elles sont souvent au format <b>CSV</b> : un texte où les valeurs sont séparées par des virgules ou des points-virgules. Avant de calculer, on vérifie les doublons, les cases vides, les unités. On choisit ensuite le graphique adapté et on lui donne un titre, des axes nommés et une source.</p>`)],
  [{q:'Enquête : la colonne C contient le mode de transport de 120 élèves. Combien viennent à vélo, et quelle part cela représente-t-il ?',s:['=NB.SI(C2:C121;"vélo") donne par exemple 18.','Part : 18 ÷ 120 = 0,15, soit 15 %.','Représentation : diagramme circulaire des modes de transport, avec titre et source.']}],
  ['Je vérifie et nettoie les données.','J’utilise la fonction adaptée (NB.SI, SOMME.SI, SI…).','Je calcule des parts en pourcentage.','Je représente avec un graphique titré et sourcé.'],
  ['Calculer sans vérifier les doublons et les cases vides.','Oublier les guillemets autour d’un critère texte.','Un graphique sans titre ni unités.'],
  ['NB.SI, SOMME.SI, SI.','CSV, données ouvertes.','Graphique : titre, axes, source.']),
 g:mix([d=>{const tot=P([20,40,60,80,100,120,200]),k=R(1,9)*tot/20;return num(`Sur ${tot} réponses, =NB.SI(…;"oui") renvoie ${k}. Quel pourcentage de « oui » cela représente-t-il ?`,k/tot*100,{unit:'%',expl:`${k} ÷ ${tot} = ${nf(k/tot)}, soit <b>${nf(k/tot*100)} %</b>.`,hint:'Part ÷ total × 100.'});},2],
  [d=>{const n=R(5,8),cls=['A','B'];const v=Array.from({length:n},()=>P(cls));if(!v.includes('A'))v[0]='A';const c=v.filter(x=>x==='A').length;return num(`La plage B2:B${n+1} contient : ${v.join(' ; ')}. Que renvoie =NB.SI(B2:B${n+1};"A") ?`,c,{expl:`On compte les cellules égales à « A » : <b>${c}</b>.`,hint:'Compte les A.'});},2],
  [d=>{const s=R(4,19),t=10;return ch(`En C2 la note est ${s}. Que renvoie =SI(C2&gt;=${t};"Acquis";"À revoir") ?`,s>=t?'Acquis':'À revoir',[s>=t?'À revoir':'Acquis','VRAI','une erreur'],{expl:`${s} ${s>=t?'≥':'&lt;'} ${t}, donc le test est ${s>=t?'vrai':'faux'} : « ${s>=t?'Acquis':'À revoir'} ».`,hint:'Le premier résultat si le test est vrai, le second sinon.'});},2],
  [bank([
   ['Un fichier CSV est…','un fichier texte où les valeurs sont séparées par des virgules ou des points-virgules',['une image compressée','un programme','une vidéo'],'Format simple lu par tous les tableurs.'],
   ['Les données ouvertes (open data) sont…','des données publiées librement et réutilisables',['des données secrètes','des mots de passe','des données payantes uniquement'],'Exemple : data.gouv.fr.'],
   ['Avant de calculer sur des données importées, on vérifie…','les doublons, les cases vides et les unités',['la couleur des cellules','la police','le nom du fichier seulement'],'Des données sales faussent les résultats.'],
   ['Quelle fonction additionne seulement les montants d’une catégorie ?','SOMME.SI',['NB','MAX','SI'],'SOMME.SI(plage;critère;plage_somme).',2],
   ['Un tableau croisé dynamique sert à…','résumer un grand tableau (totaux, moyennes par catégorie)',['dessiner une image','chiffrer un fichier','écrire un texte'],'Il regroupe et calcule automatiquement.',3],
   {tf:'Un graphique doit avoir un titre, des axes nommés et une source.',v:true,e:'Sinon il est difficile à interpréter.'}]),2])},

{id:'pix3b',name:'Gérer son identité numérique',icon:'🪪',domain:'Communication',
 refs:[D2+', compétence 2.4 « S’insérer dans le monde numérique »',D4+', compétence 4.2 « Protéger les données personnelles et la vie privée »',CRCN],
 tip:'Sépare tes usages : un profil privé pour les amis, une adresse électronique sérieuse (prenom.nom) pour les stages, l’orientation et les démarches.',
 c:C(`En 3e, tu cherches un <b>stage d’observation</b>, tu prépares ton orientation : les adultes que tu contactes peuvent taper ton nom dans un moteur de recherche. Gérer son <b>identité numérique</b>, c’est contrôler l’image que l’on donne et distinguer usages personnels et usages scolaires ou professionnels.`,
  [T('Plusieurs identités, une personne',`<p>Une personne peut avoir plusieurs <b>profils</b> : pseudonymes pour les jeux, compte privé pour les amis, adresse électronique « sérieuse » pour les démarches. Une <b>e-réputation</b> se construit avec ce que l’on publie et ce que les autres publient sur soi.</p>`),
   T('Construire une présence positive',`<p>Choisir une adresse électronique sobre (prenom.nom@…), une photo de profil correcte, vérifier régulièrement ce qui apparaît sous son nom, supprimer les anciennes publications gênantes, demander le retrait d’un contenu qui nous concerne (à la personne, à la plateforme, puis à la CNIL si besoin). L’<b>usurpation d’identité</b> en ligne est un délit.</p>`)],
  [{q:'Emma écrit à une entreprise pour son stage avec l’adresse « lapetitefolle2011@… ». Conseils ?',s:['Créer une adresse sobre : emma.martin@… (ou utiliser celle de l’ENT si autorisé).','Objet clair, message poli avec CV et lettre en PDF.','Vérifier ce qui apparaît en tapant son nom dans un moteur de recherche.']}],
  ['Je sépare usages personnels et démarches officielles.','J’utilise une adresse électronique sobre.','Je vérifie mon e-réputation.','Je demande le retrait des contenus gênants.'],
  ['Utiliser un pseudo fantaisiste pour une demande de stage.','Penser qu’un pseudonyme rend totalement anonyme.','Laisser en public d’anciennes publications gênantes.'],
  ['Plusieurs profils, une seule personne.','E-réputation.','Usurpation d’identité : délit.']),
 g:mix([bank([
  ['Pour une demande de stage, quelle adresse électronique choisir ?','emma.martin@exemple.fr',['lapetitefolle2011@exemple.fr','xXdarkgamerXx@exemple.fr','bisous.bisous@exemple.fr'],'Une adresse sobre fait sérieux.'],
  ['L’e-réputation, c’est…','l’image d’une personne telle qu’elle apparaît en ligne',['le nombre de ses amis','sa note en informatique','son mot de passe'],'Elle se construit avec les traces en ligne.'],
  ['Un pseudonyme rend-il totalement anonyme ?','non, car d’autres traces peuvent permettre de t’identifier',['oui, toujours','oui, sur tous les sites','oui, s’il est long'],'L’adresse IP, les photos ou les amis communs peuvent te trahir.'],
  ['Quelqu’un crée un faux profil à ton nom. C’est…','une usurpation d’identité, un délit',['une blague autorisée','un hommage','un droit'],'On peut porter plainte et le signaler.'],
  ['Un ami publie une photo gênante de toi. Première étape ?','lui demander de la retirer',['publier une photo gênante de lui','ne rien faire','fermer tous ses comptes'],'Puis signaler à la plateforme si besoin.'],
  ['Si la plateforme ne retire pas un contenu qui te concerne, tu peux saisir…','la CNIL',['la SNCF','la mairie','le CDI'],'La CNIL veille au respect du RGPD.',2],
  ['Pourquoi vérifier ce qui apparaît quand on tape son nom ?','pour savoir ce qu’un recruteur ou un établissement pourrait voir',['pour gagner des abonnés','pour effacer Internet','ce n’est jamais utile'],'C’est le premier geste pour gérer son e-réputation.'],
  ['Une photo de profil pour une plateforme d’orientation doit être…','sobre et correcte',['drôle et grimaçante','la photo d’un ami','une image de jeu vidéo'],'Elle donne une première impression.'],
  {tf:'Séparer un compte personnel privé d’un compte pour les démarches est une bonne pratique.',v:true,e:'On contrôle mieux ce que chacun voit.'},
  {tf:'Supprimer son compte efface automatiquement toutes les copies de ses anciennes publications.',v:false,e:'Des copies ou captures peuvent subsister.',d:2},
  ['Les paramètres de confidentialité d’un réseau social permettent…','de choisir qui voit tes publications et ton profil',['de changer ton âge','d’accélérer l’application','de voir les mots de passe des autres'],'Public, amis, personnalisé.',2],
  ['Un site demande ta date de naissance complète pour un simple jeu. Tu…','te demandes si c’est nécessaire et limites les informations données',['la donnes toujours','donnes aussi ton adresse','donnes celle de tes parents'],'Principe de minimisation des données.',3]]),1])},

{id:'pix3c',name:'Produire un document complexe',icon:'📚',domain:'Création de contenu',
 refs:[D3+', compétences 3.1 « Développer des documents textuels » et 3.3 « Adapter les documents à leur finalité »',CRCN],
 tip:'Rapport de stage : page de garde, sommaire automatique, parties avec styles, illustrations légendées, annexes, sources — puis export PDF.',
 c:C(`Le <b>rapport de stage</b> de 3e est souvent le premier long document à produire : 8 à 15 pages, avec page de garde, sommaire, parties, illustrations, annexes. Le traitement de texte a les outils pour qu’il soit propre et cohérent, et pour l’adapter à son usage (impression, lecture à l’écran, diffusion).`,
  [T('Outils du document long',`<p><b>Styles</b> pour tous les titres, <b>sommaire</b> (table des matières) automatique, <b>numérotation</b> des pages (sauf sur la page de garde), <b>sauts de page</b> avant chaque partie, <b>légendes</b> numérotées, <b>notes de bas de page</b>, <b>en-têtes</b> différents selon les sections.</p>`),
   T('Adapter à la finalité',`<p>Pour imprimer : marges suffisantes, images en bonne résolution. Pour l’écran : liens cliquables, sommaire avec liens. Pour diffuser : <b>PDF</b> (mise en page fixe, poids raisonnable). <b>Accessibilité</b> : titres structurés, texte alternatif pour les images, contraste suffisant, police lisible.</p>`)],
  [{q:'Organiser le rapport de stage dans une boulangerie.',s:['Page de garde (nom, classe, entreprise, dates), sans numéro de page.','Sommaire automatique ; parties en Titre 1 (L’entreprise, Les métiers, Mon stage, Bilan) avec sauts de page.','Photos légendées, annexes (planning), sources ; export en PDF.']}],
  ['Je construis le plan avec les styles.','J’insère sommaire, pagination et sauts de page.','J’ajoute légendes, notes et annexes.','J’adapte le document à son usage et je l’exporte.'],
  ['Numéroter la page de garde.','Créer le sommaire à la main.','Oublier le texte alternatif des images.'],
  ['Page de garde, sommaire, parties, annexes.','Sauts de page et sections.','Accessibilité : titres, texte alternatif, contraste.']),
 g:mix([d=>{const ord=['page de garde','sommaire','introduction','développement en parties','conclusion','annexes'];const n=d===1?4:d===2?5:6;const st=R(0,6-n);const part=ord.slice(st,st+n);return order('Remets dans l’ordre les éléments d’un rapport de stage :',part,{expl:part.join(' → '),hint:'Du début à la fin du document.'});},2],
  [bank([
   ['Comment faire commencer chaque partie sur une nouvelle page ?','avec un saut de page',['avec des retours à la ligne','avec une image vide','en changeant la police'],'Fiable même si le texte change.'],
   ['Le texte alternatif d’une image sert à…','la décrire pour les personnes qui ne la voient pas (lecteur d’écran)',['la compresser','la protéger','la rendre plus nette'],'C’est une règle d’accessibilité.'],
   ['Pourquoi ne pas numéroter la page de garde ?','par convention, elle n’affiche pas de numéro',['c’est impossible','elle n’est pas imprimée','elle est en PDF'],'On utilise un style de page sans numéro.',2],
   ['Une annexe contient…','des documents complémentaires (planning, organigramme)',['le titre du rapport','le sommaire','la conclusion'],'Placée en fin de document.'],
   ['Pour un document lu à l’écran, un sommaire avec liens permet…','d’aller directement à une partie',['d’imprimer plus vite','de compresser le fichier','de le traduire'],'Navigation facilitée.',2],
   ['Quel format pour envoyer le rapport final au professeur ?','PDF',['ODT avec images séparées','MP4','TXT'],'Mise en page conservée.'],
   ['Légender une image, c’est…','écrire sous elle ce qu’elle montre (et sa source)',['la recadrer','la mettre en arrière-plan','la supprimer'],'Exemple : « Figure 2 – Le four à pain ».'],
   ['Un bon contraste texte/fond améliore…','la lisibilité pour tous',['la taille du fichier','la vitesse d’impression','l’orthographe'],'Indispensable pour l’accessibilité.'],
   {tf:'Le sommaire automatique se met à jour quand on ajoute une partie stylée.',v:true,e:'Il faut parfois cliquer sur « mettre à jour ».'},
   ['Différents en-têtes selon les parties s’obtiennent avec…','des sections (ou styles de page) différents',['des couleurs','des tableaux','des images'],'Chaque section a sa mise en page.',3]]),2])},

{id:'pix3d',name:'Automatiser une tâche : tableur et programme',icon:'⚙️',domain:'Création de contenu',
 refs:[D3+', compétence 3.4 « Programmer »',D1+', compétence 1.3 « Traiter des données »',CRCN],
 tip:'Une tâche répétitive = une boucle ou une formule recopiée. Une décision = une condition. Un résultat qui dépend d’une valeur = une variable ou une référence de cellule.',
 c:C(`Calculer 300 moyennes, convertir une liste de températures, compter des mots : faire la même chose à la main est long et source d’erreurs. On <b>automatise</b> avec des formules recopiées dans un tableur ou avec un petit <b>programme</b> (Scratch, Python).`,
  [T('Automatiser avec le tableur',`<p>Une formule écrite une fois et <b>recopiée</b> traite toutes les lignes. Les références <b>absolues</b> ($B$1) fixent un paramètre commun (un taux, un seuil). Les fonctions <b>SI</b>, <b>NB.SI</b> prennent des décisions et comptent automatiquement.</p>`),
   T('Automatiser avec un programme',`<p>En Python : une <b>variable</b> (<code>total = 0</code>), une <b>boucle</b> (<code>for i in range(10):</code>), une <b>condition</b> (<code>if note &gt;= 10:</code>), une <b>fonction</b> qui regroupe des instructions réutilisables (<code>def moyenne(liste):</code>). On teste avec des cas simples dont on connaît le résultat.</p>`)],
  [{q:'Convertir 50 températures de degrés Celsius en degrés Fahrenheit.',s:['Tableur : en B2, =A2*9/5+32, puis recopier jusqu’à B51.','Python : for c in liste: print(c*9/5+32)','Test : 0 °C donne 32 °F et 100 °C donne 212 °F.']}],
  ['Je repère ce qui se répète.','Je choisis formule recopiée ou boucle.','Je mets les paramètres communs en référence absolue ou en variable.','Je teste avec des cas connus.'],
  ['Recopier à la main 50 calculs.','Oublier de remettre le compteur à zéro.','Ne pas tester avec un cas dont on connaît le résultat.'],
  ['Répétition → boucle / recopie.','Décision → condition.','Tester avec des cas connus.']),
 g:mix([d=>{const n=R(3,9),s=R(1,4);let t=0;for(let i=0;i<n;i++)t+=s;return num(`Programme Python :<br><code>total = 0</code><br><code>for i in range(${n}):</code><br><code>&nbsp;&nbsp;&nbsp;&nbsp;total = total + ${s}</code><br>Que vaut total à la fin ?`,t,{expl:`La boucle tourne ${n} fois et ajoute ${s} à chaque tour : ${n} × ${s} = <b>${t}</b>.`,hint:'range(n) fait n tours.'});},2],
  [d=>{const n=R(4,8);const t=n*(n-1)/2;return num(`Programme Python :<br><code>total = 0</code><br><code>for i in range(${n}):</code><br><code>&nbsp;&nbsp;&nbsp;&nbsp;total = total + i</code><br>Que vaut total à la fin ? (range(${n}) donne 0, 1, …, ${n-1})`,t,{expl:`0 + 1 + … + ${n-1} = <b>${t}</b>.`,hint:'Additionne les valeurs de i.'});},1],
  [d=>{const c=P([0,10,20,25,30,35,40,100]);return num(`Avec la formule =A2*9/5+32, quelle valeur obtient-on pour ${c} °C ?`,c*9/5+32,{unit:'°F',expl:`${c} × 9 ÷ 5 + 32 = <b>${nf(c*9/5+32)}</b> °F.`,hint:'Multiplie par 9, divise par 5, ajoute 32.'});},2],
  [d=>{const x=R(5,18);return ch(`Python : <code>note = ${x}</code> puis <code>if note &gt;= 10: print("Admis")</code> <code>else: print("Ajourné")</code>. Qu’affiche le programme ?`,x>=10?'Admis':'Ajourné',[x>=10?'Ajourné':'Admis','rien','une erreur'],{expl:`${x} ${x>=10?'≥':'&lt;'} 10 : « ${x>=10?'Admis':'Ajourné'} ».`,hint:'Teste la condition.'});},2],
  [bank([
   ['Dans un tableur, pour appliquer un même calcul à 300 lignes, on…','écrit la formule une fois et on la recopie',['tape 300 formules à la main','utilise une calculatrice','change de logiciel'],'La recopie adapte les références.'],
   ['À quoi sert une fonction (def) en Python ?','regrouper des instructions réutilisables',['afficher une image','supprimer une variable','éteindre l’ordinateur'],'On l’appelle autant de fois que nécessaire.',2],
   ['Pourquoi tester un programme avec 0 °C → 32 °F ?','c’est un cas dont on connaît le résultat',['c’est obligatoire en Python','c’est plus rapide','pour casser le programme'],'Un cas connu permet de détecter une erreur.'],
   {tf:'Dans range(5), la dernière valeur est 5.',v:false,e:'range(5) donne 0, 1, 2, 3, 4.',d:2}]),2])},

{id:'pix3e',name:'Diagnostiquer un problème technique',icon:'🩺',domain:'Environnement numérique',
 refs:[D5+', compétences 5.1 « Résoudre des problèmes techniques » et 5.2 « Évoluer dans un environnement numérique »',CRCN],
 tip:'Isoler la cause : le problème vient-il du matériel, du logiciel, du réseau ou du compte ? Teste sur un autre appareil, un autre réseau, un autre compte.',
 c:C(`« Internet ne marche pas » peut cacher des causes très différentes : Wi-Fi coupé, box en panne, site indisponible, navigateur bloqué… En 3e, on apprend à <b>diagnostiquer</b> : isoler la cause en testant méthodiquement, et à connaître les éléments d’un <b>réseau</b>.`,
  [T('Isoler la cause',`<p>On compare : le problème existe-t-il sur un autre appareil ? avec un autre réseau ? dans un autre navigateur ? avec un autre compte ? Chaque réponse élimine des causes. On lit les <b>messages d’erreur</b> (« 404 » : page introuvable ; « pas de connexion » : réseau) et on note ce qu’on a essayé.</p>`),
   T('Réseau et stockage',`<p>Un <b>réseau</b> relie des appareils ; la <b>box</b> (routeur) relie la maison à Internet. Chaque appareil a une <b>adresse IP</b>. Le <b>serveur</b> héberge les sites. Un appareil lent peut manquer d’<b>espace de stockage</b> ou de <b>mémoire vive</b>, ou avoir trop d’applications ouvertes.</p>`)],
  [{q:'Sur ton ordinateur, aucun site ne s’ouvre, mais sur ton téléphone (même Wi-Fi) tout fonctionne. Diagnostic ?',s:['Le Wi-Fi et la box fonctionnent (le téléphone y accède).','Le problème vient donc de l’ordinateur : Wi-Fi désactivé, mode avion, navigateur…','Vérifier la connexion de l’ordinateur, essayer un autre navigateur, redémarrer.']}],
  ['Je décris précisément le symptôme.','Je compare avec un autre appareil, réseau, navigateur ou compte.','J’élimine les causes une par une.','Je note ce que j’ai essayé.'],
  ['Changer plusieurs réglages à la fois.','Accuser Internet alors que seul un site est en panne.','Supprimer des fichiers au hasard pour libérer de l’espace.'],
  ['Matériel, logiciel, réseau ou compte ?','Erreur 404 : page introuvable.','Box, IP, serveur.']),
 g:mix([bank([
  ['Un seul site ne s’ouvre pas, les autres oui. La cause probable ?','le site lui-même est indisponible',['ta box est en panne','ton clavier est cassé','ton mot de passe est faux'],'Les autres sites fonctionnent : ta connexion va bien.'],
  ['Aucun appareil de la maison n’accède à Internet. Que vérifier ?','la box (allumée, voyants, redémarrage)',['le navigateur d’un seul ordinateur','la souris','la luminosité de l’écran'],'Tous les appareils sont touchés : cause commune.'],
  ['L’erreur « 404 » signifie…','la page demandée est introuvable',['l’ordinateur est infecté','le Wi-Fi est coupé','la batterie est vide'],'L’adresse est erronée ou la page a été supprimée.'],
  ['Ton compte ENT ne fonctionne pas, mais celui d’un camarade oui sur le même ordinateur. Le problème vient…','de ton compte (identifiant, mot de passe, droits)',['de l’ordinateur','du réseau','de l’écran'],'Le reste fonctionne avec un autre compte.',2],
  ['Une adresse IP identifie…','un appareil sur un réseau',['un mot de passe','un fichier','une application'],'Comme une adresse postale.',2],
  ['La box (routeur) sert à…','relier les appareils de la maison à Internet',['stocker toutes les vidéos','imprimer','protéger contre tous les virus'],'Elle fait le lien entre réseau local et Internet.'],
  ['Un téléphone devient très lent. Une cause possible ?','l’espace de stockage est presque plein',['la coque est rouge','l’écran est trop propre','le volume est trop bas'],'Libérer de l’espace (photos sauvegardées, applications inutiles).'],
  ['Un serveur est…','un ordinateur qui fournit des services ou héberge des sites',['un câble','un logiciel de dessin','une souris sans fil'],'Il répond aux demandes des autres appareils.',2],
  ['Pour savoir si le problème vient du navigateur, on…','essaie un autre navigateur',['change de clavier','éteint l’écran','supprime ses photos'],'Si ça marche ailleurs, le navigateur est en cause.'],
  {tf:'Noter ce qu’on a déjà essayé aide la personne qui vient dépanner.',v:true,e:'Elle gagne du temps.'},
  {tf:'Un message d’erreur ne sert à rien : il vaut mieux le fermer sans le lire.',v:false,e:'Il indique souvent la cause.'},
  ['La mémoire vive (RAM) sert à…','faire fonctionner les programmes ouverts',['stocker durablement les photos','se connecter au Wi-Fi','imprimer'],'Elle se vide à l’extinction.',3]]),3])},

{id:'pix3f',name:'Sauvegardes et authentification',icon:'💾',domain:'Protection et sécurité',
 refs:[D4+', compétence 4.1 « Sécuriser l’environnement numérique »',D5+', compétence 5.2',CRCN],
 tip:'Règle 3-2-1 : 3 copies de tes fichiers importants, sur 2 supports différents, dont 1 hors de chez toi (par exemple dans un espace en ligne).',
 c:C(`Panne, vol, rançongiciel, fausse manipulation : un fichier important peut disparaître. Les <b>sauvegardes</b> régulières protègent ton travail. L’<b>authentification</b> forte protège tes comptes, et un <b>gestionnaire de mots de passe</b> aide à avoir des mots de passe uniques.`,
  [T('Sauvegarder',`<p>Supports : disque externe, clé USB, espace de stockage en ligne (« nuage », ENT). <b>Règle 3-2-1</b> : 3 copies, 2 supports différents, 1 copie à l’extérieur. Une sauvegarde <b>automatique</b> régulière est plus sûre qu’une sauvegarde « quand j’y pense ». On vérifie qu’on sait <b>restaurer</b> un fichier. La <b>synchronisation</b> copie aussi les suppressions : ce n’est pas toujours une vraie sauvegarde.</p>`),
   T('S’authentifier',`<p>Facteurs d’authentification : ce que je <b>sais</b> (mot de passe, code), ce que je <b>possède</b> (téléphone, clé de sécurité), ce que je <b>suis</b> (empreinte, visage). L’<b>authentification à deux facteurs</b> combine deux de ces catégories. Un <b>gestionnaire de mots de passe</b> retient des mots de passe uniques et longs, protégés par un mot de passe maître.</p>`)],
  [{q:'Ton rapport de stage n’existe que sur ton ordinateur. Comment appliquer la règle 3-2-1 ?',s:['Copie 1 : l’ordinateur.','Copie 2 : une clé USB ou un disque externe (2e support).','Copie 3 : ton espace en ligne de l’ENT (copie hors de chez toi).']}],
  ['Je sauvegarde régulièrement, si possible automatiquement.','J’applique la règle 3-2-1.','J’active la double authentification.','J’utilise un gestionnaire de mots de passe.'],
  ['Croire que la synchronisation protège d’une suppression.','Garder la seule copie sur une clé USB.','Utiliser le même mot de passe partout.'],
  ['3 copies, 2 supports, 1 à l’extérieur.','Savoir, posséder, être.','Gestionnaire de mots de passe.']),
 g:mix([sort({'ce que je sais':['un mot de passe','un code PIN','la réponse à une question secrète'],'ce que je possède':['un téléphone qui reçoit un code','une clé de sécurité USB','une carte à puce'],'ce que je suis':['mon empreinte digitale','la reconnaissance de mon visage','la reconnaissance de mon iris']},{q:'« %s » est un facteur d’authentification de type…'}),2],
  [bank([
   ['La règle 3-2-1 des sauvegardes, c’est…','3 copies, 2 supports différents, 1 copie à l’extérieur',['3 mots de passe, 2 comptes, 1 antivirus','3 clés USB dans le même tiroir','sauvegarder 3 fois par an'],'Elle protège contre la plupart des pertes.'],
   ['Pourquoi une copie hors de chez soi ?','pour se protéger d’un vol, d’un incendie ou d’un dégât des eaux',['pour qu’elle soit plus rapide','c’est interdit de garder des copies chez soi','pour la partager avec tout le monde'],'Une catastrophe locale ne détruit pas tout.'],
   ['La synchronisation d’un dossier…','reproduit aussi les suppressions : ce n’est pas toujours une sauvegarde',['empêche toute perte','chiffre les fichiers','remplace l’antivirus'],'Un fichier effacé peut l’être partout.',2],
   ['Un gestionnaire de mots de passe…','retient des mots de passe uniques protégés par un mot de passe maître',['donne ton mot de passe aux autres','remplace l’antivirus','supprime tes comptes'],'Tu n’as qu’un mot de passe à retenir.',2],
   ['L’authentification à deux facteurs combine par exemple…','un mot de passe et un code reçu sur le téléphone',['deux mots de passe','deux identifiants','un mot de passe écrit deux fois'],'Deux catégories différentes.'],
   ['Contre un rançongiciel, la meilleure protection pour ses fichiers est…','une sauvegarde récente non connectée en permanence',['payer la rançon','éteindre l’écran','changer de fond d’écran'],'On restaure les fichiers sans payer.',3],
   ['Tester la restauration d’une sauvegarde sert à…','vérifier qu’on peut vraiment récupérer ses fichiers',['effacer la sauvegarde','alourdir l’ordinateur','changer de mot de passe'],'Une sauvegarde illisible ne sert à rien.',2],
   {tf:'Une clé USB unique suffit comme sauvegarde fiable.',v:false,e:'Une clé se perd ou se casse facilement.'},
   {tf:'Une sauvegarde automatique régulière est plus sûre qu’une sauvegarde faite de temps en temps.',v:true,e:'On ne dépend pas de sa mémoire.'}]),2])},

{id:'pix3g',name:'Licences, droits et usages responsables',icon:'📜',domain:'Citoyenneté numérique',
 refs:[D2+', compétence 2.2 « Partager et publier »',D3+', compétence 3.3 « Adapter les documents à leur finalité »',CRCN],
 tip:'Pour réutiliser une œuvre : vérifie sa licence, respecte ses conditions (citer, pas d’usage commercial, pas de modification…) et crédite l’auteur.',
 c:C(`Une musique pour une vidéo de classe, une image pour une affiche, un logiciel à installer : tout contenu numérique est soumis à des <b>droits</b>. Connaître le <b>droit d’auteur</b>, les <b>licences</b> et la différence entre <b>logiciel libre</b> et <b>propriétaire</b> permet d’utiliser et de partager de façon légale et responsable.`,
  [T('Droit d’auteur et licences',`<p>En France, le droit d’auteur protège une œuvre dès sa création, sans formalité, pendant toute la vie de l’auteur et 70 ans après sa mort ; ensuite, elle entre dans le <b>domaine public</b>. Une <b>licence</b> précise ce que l’auteur autorise. Les licences <b>Creative Commons</b> combinent BY (citer), NC (pas d’usage commercial), ND (pas de modification), SA (partage dans les mêmes conditions). <b>CC0</b> : l’auteur renonce à ses droits autant que la loi le permet.</p>`),
   T('Logiciels, téléchargement et sobriété',`<p>Un <b>logiciel libre</b> (LibreOffice, Firefox, VLC) peut être utilisé, étudié, modifié et redistribué. Un logiciel <b>propriétaire</b> impose les conditions de son éditeur. Télécharger ou partager des œuvres protégées sans autorisation est illégal. Usage responsable aussi pour la planète : le numérique consomme de l’énergie et des ressources (fabrication des appareils surtout) ; garder ses appareils plus longtemps et limiter la vidéo en haute définition réduit l’impact.</p>`)],
  [{q:'Pour l’affiche du club, Lina trouve une photo sous licence CC BY-NC. Peut-elle l’utiliser ? Et pour vendre des tee-shirts ?',s:['BY : citer l’auteur ; NC : pas d’usage commercial.','Affiche du club (non commerciale) : oui, en créditant l’auteur et la licence.','Tee-shirts vendus : non, sans autorisation de l’auteur.']}],
  ['Je vérifie la licence de chaque contenu.','Je respecte ses conditions.','Je crédite l’auteur et la licence.','Je préfère les œuvres libres ou du domaine public.'],
  ['Penser qu’une œuvre sans mention de licence est libre.','Utiliser une œuvre ND en la modifiant.','Oublier que fabriquer un appareil a un fort impact environnemental.'],
  ['Droit d’auteur : vie + 70 ans.','CC : BY, NC, ND, SA ; CC0.','Libre ≠ gratuit ; propriétaire.']),
 g:mix([d=>{const y=R(1880,1960),a=R(25,90);const m=y+a,pub=m+70;const now=2026;return ch(`Un photographe est né en ${y} et mort en ${m}. Selon la règle générale (droits jusqu’à 70 ans après la mort de l’auteur), ses œuvres sont-elles dans le domaine public en ${now} ?`,pub<now?'Oui':'Non',[pub<now?'Non':'Oui'],{expl:`Les droits durent jusqu’à 70 ans après la mort (jusqu’au 31 décembre de la 70e année) : ${m} + 70 = ${pub}. ${pub<now?`Depuis le 1er janvier ${pub+1}, ses œuvres sont dans le domaine public.`:`Elles entreront dans le domaine public le 1er janvier ${pub+1}.`}`,hint:'Année de décès + 70.'});},2],
  [sort({'logiciel libre':['LibreOffice','Firefox','VLC','GIMP','Audacity'],'logiciel propriétaire':['Microsoft Word','Adobe Photoshop','macOS','Microsoft Excel']},{q:'« %s » est un…'}),1],
  [bank([
   ['Une photo sous licence CC BY-ND peut-elle être recadrée et publiée ?','non, car ND interdit la modification',['oui, sans condition','oui, si on ne cite pas l’auteur','oui, si on la vend'],'On peut la diffuser telle quelle, en citant l’auteur.',2],
   ['Une œuvre sans indication de licence est…','protégée par défaut par le droit d’auteur',['libre de droits','dans le domaine public','gratuite pour tous les usages'],'Il faut l’autorisation de l’auteur.'],
   ['La licence CC0 signifie que…','l’auteur renonce à ses droits autant que la loi le permet',['l’œuvre est interdite','l’œuvre coûte 0 euro mais est protégée','il faut payer l’auteur'],'Réutilisation très libre.',2],
   ['Un logiciel libre est…','un logiciel qu’on peut utiliser, étudier, modifier et redistribuer',['forcément payant','un logiciel sans mises à jour','un virus'],'Libre ne veut pas dire seulement gratuit.'],
   ['Quelle part de l’impact environnemental du numérique vient surtout de la fabrication des appareils ?','la plus grande part',['aucune','une part négligeable','seulement celle des câbles'],'Garder ses appareils plus longtemps réduit l’impact.',3],
   ['Un geste de sobriété numérique :','garder son téléphone plus longtemps et le faire réparer',['changer de téléphone chaque année','regarder toutes les vidéos en très haute définition','laisser les appareils allumés la nuit'],'La fabrication pèse lourd.'],
   ['Télécharger un film récent sur un site non autorisé est…','illégal',['légal s’il est gratuit','légal pour les mineurs','légal si on ne le partage pas'],'Il viole le droit d’auteur.'],
   {tf:'Libre et gratuit veulent toujours dire la même chose.',v:false,e:'Libre concerne les droits d’usage ; certains logiciels gratuits ne sont pas libres.',d:2}]),2])},

{id:'pix3h',name:'Préparer la certification Pix de 3e',icon:'🏅',domain:'Pix',
 refs:[NS+' : certification Pix obligatoire en 3e (32 questions adaptatives, 1 h 45 de test, 2 h de session avec l’accueil), niveau global attendu : niveau 3, sans incidence sur l’obtention du DNB',CRCN],
 tip:'Avant la session : avoir travaillé ses parcours Pix, connaître ses identifiants, arriver à l’heure. Pendant : lire chaque consigne, gérer son temps, ne communiquer avec personne.',
 c:C(`En 3e, tous les élèves passent la <b>certification Pix</b>. Elle délivre un <b>certificat</b> qui atteste du niveau atteint dans les compétences numériques du CRCN. C’est un document officiel utile pour la suite (lycée, CAP, stages).`,
  [T('Déroulement',`<p>La certification se passe au collège, dans une session <b>surveillée</b>, sur une période fixée au printemps. Elle dure environ <b>2 heures</b> : un temps d’accueil et d’installation, puis <b>1 h 45</b> de test. Le test compte <b>32 questions adaptatives</b> qui portent sur les compétences travaillées pendant les parcours. Le niveau global attendu en fin de 3e est le <b>niveau 3</b>. Le résultat n’intervient pas dans l’obtention du brevet (DNB).</p>`),
   T('Bien se préparer',`<p>Avant : faire les parcours de préparation proposés par les professeurs, monter en niveau dans le plus de compétences possible, vérifier qu’on connaît son <b>identifiant</b> et son <b>mot de passe</b> Pix. Pendant : écouter les consignes du surveillant, ranger son téléphone, gérer son temps (environ 3 minutes par question en moyenne), lire chaque consigne et chaque fichier. Certaines épreuves interdisent de quitter la page : on reste dans la fenêtre de l’épreuve.</p>`)],
  [{q:'Planifier sa préparation sur 4 semaines avant la certification.',s:['Semaine 1 : regarder son profil Pix et repérer les compétences de niveau faible.','Semaines 2 et 3 : faire les parcours de préparation, revoir les tutoriels des épreuves ratées.','Semaine 4 : vérifier ses identifiants, refaire un parcours complet en temps limité.']}],
  ['Je repère mes compétences faibles.','Je fais les parcours de préparation.','Je vérifie mes identifiants avant la session.','Le jour J, je gère mon temps et je respecte les consignes.'],
  ['Découvrir le jour même qu’on a oublié son mot de passe.','Passer trop de temps sur une seule question.','Utiliser son téléphone pendant la session.'],
  ['32 questions, 1 h 45 de test.','Niveau global attendu : 3.','Sans incidence sur le DNB ; certificat officiel.']),
 g:mix([d=>{const q=32,m=105,used=R(5,25)*3,done=R(4,14);const left=q-done,tl=m-used;return num(`Pendant la certification (32 questions en 1 h 45), tu as répondu à ${done} questions en ${used} minutes. Combien de minutes te reste-t-il pour les ${left} questions restantes ?`,tl,{unit:'min',expl:`1 h 45 = 105 min ; 105 − ${used} = <b>${tl} min</b>, soit environ ${nf(Math.round(tl/left*10)/10)} min par question.`,hint:'1 h 45 = 105 min.'});},2],
  [bank([
   ['Combien de questions compte la certification Pix de 3e ?','32',['16','50','100'],'Des questions adaptatives.'],
   ['Quelle est la durée du test de certification ?','1 h 45',['30 min','4 h','10 min'],'Dans une session d’environ 2 heures avec l’accueil.'],
   ['Quel niveau global est attendu en fin de 3e ?','le niveau 3',['le niveau 8','le niveau 1','le niveau 6'],'Niveau fixé par la note de service de 2026.',2],
   ['La certification Pix compte-t-elle pour l’obtention du brevet ?','non',['oui, pour 50 points','oui, elle est éliminatoire','oui, pour l’oral'],'Elle est obligatoire mais sans incidence sur le DNB.'],
   ['Avant la session, il faut absolument vérifier…','qu’on connaît son identifiant et son mot de passe Pix',['la couleur de son clavier','son nombre d’abonnés','la météo'],'Sans identifiants, on perd du temps.'],
   ['Pendant la certification, ton téléphone doit être…','rangé et éteint selon les consignes',['posé sur la table','utilisé pour chercher','prêté au voisin'],'C’est une épreuve surveillée.'],
   ['La certification Pix est-elle obligatoire en 3e ?','oui',['non, facultative','seulement pour les volontaires','seulement en lycée professionnel'],'Tous les élèves de 3e la passent.'],
   ['En moyenne, combien de temps peut-on consacrer à chaque question (105 min pour 32 questions) ?','un peu plus de 3 minutes',['30 secondes','10 minutes','une heure'],'105 ÷ 32 ≈ 3,3 min.',2],
   ['Comment se préparer efficacement ?','faire les parcours de préparation et retravailler ses compétences faibles',['apprendre les réponses par cœur','ne rien faire','faire passer le test par un camarade'],'Les questions s’adaptent : seules les compétences comptent.'],
   ['Que délivre la certification Pix ?','un certificat officiel du niveau atteint',['une note au bulletin seulement','un diplôme de technicien','un permis'],'Utile pour la suite des études.'],
   {tf:'Les questions de la certification s’adaptent aux réponses du candidat.',v:true,e:'Comme sur la plateforme Pix.'},
   {tf:'On peut passer la certification Pix chez soi, sans surveillance.',v:false,e:'Elle se passe au collège, en session surveillée.',d:2},
   ['Sur quoi portent les questions de la certification ?','les compétences numériques du CRCN',['le programme de mathématiques','les langues vivantes','l’histoire des arts'],'Les 16 compétences, selon le niveau atteint.',2]]),3])}
]);

})();
